	["Northfold Manor"] = "Поместье Northfold",
	["The western circle is near Thoradin's Wall, where you came in."] = "Западный круг — у Стены Торадина, откуда вы пришли.",
	["The Stone of West Binding"] = "Камень Западного Связывания",
