	["Into the Badlands"] = "В Бесплодные земли",
	["Valley of Fangs"] = "Долина Клыков",
	["Head west along the road; Lotwil's camp sits in the Dustbowl halfway to Kargath."] = "Идите на запад по дороге; лагерь Lotwil — в Пыльной чаше, на полпути к Каргату.",
	["The Dustbowl"] = "Пыльная чаша",
	["Kargath is the Horde fortress built into the cliffs at the zone's western edge."] = "Каргат — крепость Орды, встроенная в скалы на западном краю зоны.",
	["Kargath"] = "Каргат",
	["The small elementals drift across the flats just west of Lotwil's camp. Every rock elemental in the zone can drop Jarkal's Rock Elemental Shards: keep them."] = "Малые элементали дрейфуют по равнине сразу к западу от лагеря Lotwil. С любого каменного элементаля в зоне могут выпасть Jarkal's Rock Elemental Shards: сохраните их.",
	["Lesser Rock Elementals"] = "Малые каменные элементали",
	["Lotwil Veriatus"] = "Lotwil Veriatus",
	["The bigger Rock Elementals stand on the slopes north-west of the Dustbowl; each one drops a slab."] = "Крупные каменные элементали стоят на склонах к северо-западу от Пыльной чаши; с каждого выпадает плита.",
	["Rock Elementals"] = "Каменные элементали",
	["The Elder Crag Coyotes and Giant Buzzards roam the basin south of the Dustbowl. Coyotes drop both the jawbones and the fangs; only the buzzards drop wings and gizzards."] = "Старые утёсные койоты и гигантские канюки бродят в котловине к югу от Пыльной чаши. С койотов выпадают и челюсти, и клыки; крылья и желудки — только с канюков.",
	["Coyotes and buzzards"] = "Койоты и канюки",
	["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "Великие каменные элементали (42-44, намного выше вас) бродят по оврагам на юго-западе; наручи выпадают примерно с каждого пятого. Тяните по одному и отдыхайте между боями — или пропустите. По пути добивайте нужных ещё койотов и канюков.",
	["Greater Rock Elementals"] = "Великие каменные элементали",
	["Head north back to Kargath."] = "Возвращайтесь на север в Каргат.",
	["The Stonevault troggs dig around the cave mouths south of the Valley of Fangs, on the way to Agmond's End; the Bonesnappers and Shamans drop the flakes."] = "Трогги Stonevault копают у входов в пещеры к югу от Долины Клыков, по дороге к Концу Агмонда; хрупкие чешуйки выпадают с костоломов и шаманов.",
	["Stonevault troggs"] = "Трогги Stonevault",
	["Theldurin sits among the dwarven ruins at Agmond's End, south of the Valley of Fangs."] = "Theldurin сидит среди руин дворфов в Конце Агмонда, к югу от Долины Клыков.",
	["Agmond's End"] = "Конец Агмонда",
	["Follow the road north; Martek's camp is on the way."] = "Идите по дороге на север; лагерь Martek по пути.",
	["Keep north on the road; the chest lies in the Uldaman dig site, at the foot of the ruins north-west of the road."] = "Продолжайте по дороге на север; сундук — на раскопках Ульдамана, у подножия руин к северо-западу от дороги.",
	["Ancient Chest"] = "Древний сундук",
	["Head back south down the road, past the Valley of Fangs."] = "Возвращайтесь по дороге на юг, мимо Долины Клыков.",
	["Hearth to Kargath"] = "Камень возвращения — в Каргат",
	["Take the Orgrimmar zeppelin from the tower on the west side of Grom'gol."] = "Сядьте на дирижабль в Оргриммар с башни на западной стороне Гром'гола.",
	["Zeppelin to Orgrimmar"] = "Дирижабль в Оргриммар",
	["Fly to Thunder Bluff"] = "Летите в Громовой Утес",
	["Your trainer is in Thunder Bluff, one flight from Orgrimmar: Turak Runetotem (Druids) on Elder Rise, Alodan the Hopeful (Paladins). Fly on to the Crossroads from there."] = "Ваш учитель — в Громовом Утесе, в одном перелёте от Оргриммара: Turak Runetotem (друиды) на Вершине Старейшин, Alodan the Hopeful (паладины). Оттуда летите в Перекрёсток.",
	["Fly to Crossroads"] = "Летите в Перекрёсток",
	["The Crossroads"] = "Перекрёсток",
	["Head north up the road from the Crossroads to the Forgotten Pools; Regthar keeps watch on the rise above the water."] = "Идите на север по дороге от Перекрёстка к Забытым Прудам; Regthar дежурит на возвышенности над водой.",
	["Regthar Deathgate"] = "Regthar Deathgate",
	["Soothing Spices, for \"Swamp Eye\" Jarl in Dustwallow Marsh"] = "Успокаивающие специи для «Swamp Eye» Jarl в Пылевых топях",
	["The next guide heads into Dustwallow Marsh."] = "Следующий гид ведёт в Пылевые топи.",
	["Head back south to the Crossroads and fly to Ratchet."] = "Возвращайтесь на юг в Перекрёсток и летите в Кабестан.",
	["Ratchet"] = "Кабестан",
	["Head south along the coast from Ratchet to Fray Island. Klannoc Macleod stands by the arena: step on the grate to start the fight; the challengers come one at a time, then Big Will (33)."] = "Идите на юг вдоль побережья от Кабестана к острову Схватки. Klannoc Macleod стоит у арены: встаньте на решётку, чтобы начать бой; соперники выходят по одному, затем Big Will (33).",
	["The Affray"] = "Схватка",
	["Zeppelin to the Undercity"] = "Дирижабль в Подгород",
	["Get the flight path at Hammerfall"] = "Возьмите точку полёта в Молоте",
	["Get the flight path at Kargath"] = "Возьмите точку полёта в Каргате",
	["Zeppelin tower"] = "Башня дирижаблей",
	["Dustwallow Marsh & Desolace"] = "Пылевые топи и Пустоши",
	["Fly to Camp Taurajo"] = "Летите в Лагерь Таурахо",
	["Head east from Camp Taurajo along the road into the marsh. The burned-out Shady Rest Inn stands beside it just past the border; the shield, the badge and the hoofprints are in and beside the ruin."] = "Идите на восток от Лагеря Таурахо по дороге в топи. Сгоревшая таверна «Тихий приют» стоит у дороги сразу за границей; щит, значок и следы копыт — в руинах и рядом с ними.",
	["Shady Rest Inn"] = "Таверна «Тихий приют»",
	["Take the road north at the fork to the ogre village of Brackenwall."] = "На развилке сверните на север к деревне огров Бракенвол.",
	["Brackenwall Village"] = "Деревня Бракенвол",
	["Ogron waits in the Quagmire east of the village. Follow him to Reethe and keep him alive through the fight that breaks out."] = "Ogron ждёт в трясине к востоку от деревни. Идите за ним к Reethe и не дайте ему погибнуть в завязавшейся драке.",
	["Questioning Reethe"] = "Допрос Reethe",
	["Head north to Witch Hill. Stinky stands at the foot of the hill; escort him while he gathers Bogbean Leaves just south of it."] = "Идите на север к Ведьминому холму. Stinky стоит у подножия; сопровождайте его, пока он собирает листья болотных бобов чуть южнее.",
	["Stinky Ignatz"] = "Stinky Ignatz",
	["The Mirefin murlocs crowd the coast east and north-east of Witch Hill; every kind drops heads."] = "Мурлоки Mirefin толпятся на побережье к востоку и северо-востоку от Ведьминого холма; головы выпадают со всех.",
	["Mirefin murlocs"] = "Мурлоки Mirefin",
	["Soothing Spices, for \"Swamp Eye\" Jarl"] = "Успокаивающие специи для «Swamp Eye» Jarl",
	["Jarl lives in the Swamplight Manor south-east of Witch Hill."] = "Jarl живёт в поместье Swamplight к юго-востоку от Ведьминого холма.",
	["Swamp Eye Jarl"] = "Swamp Eye Jarl",
	["Head west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "Возвращайтесь на запад через топи. Пауки-плевальщики Darkfang на гребнях к северу от Бракенвола роняют ядовитые железы. В тех же лесах крадутся лазутчики Терамора (35-36): они в незаметности, смотрите внимательно.",
	["Darkfang spiders"] = "Пауки Darkfang",
	["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "Пауки Darkmist кишат у входа в пещеру к северо-западу от Бракенвола; глаза выпадают со всех.",
	["Darkmist Cavern"] = "Пещера Darkmist",
	["Head east back to the Swamplight Manor."] = "Возвращайтесь на восток в поместье Swamplight.",
	["Head back west to Brackenwall with the head."] = "Отнесите голову обратно на запад, в Бракенвол.",
	["Hearth to Ratchet"] = "Камень возвращения — в Кабестан",
	["Fly to Shadowprey Village"] = "Летите в Деревню Теневой Охоты",
	["Shadowprey Village"] = "Деревня Теневой Охоты",
	["Head north-east to the Valley of Spears. Melizza is held in the Maraudine centaur camp; free her and escort her out east of the valley."] = "Идите на северо-восток в Долину Копий. Melizza в плену в лагере кентавров Мародин; освободите её и выведите из долины на восток.",
	["Melizza Brimbuzzle"] = "Melizza Brimbuzzle",
	["Hornizz waits at the goblin camp on the west side of the Kodo Graveyard."] = "Hornizz ждёт в лагере гоблинов на западной стороне Кладбища кодо.",
	["Kodo Graveyard"] = "Кладбище кодо",
	["Rigger Gizelton's caravan stops on the road at the edge of Mannoroc Coven. Escort it east past the coven; demons attack it twice."] = "Караван Rigger Gizelton останавливается на дороге у края Ковена Маннорок. Сопроводите его на восток мимо ковена; демоны нападут дважды.",
	["Gizelton Caravan"] = "Караван Gizelton",
	["The caravan ends at Smeed's camp on the east side of the Kodo Graveyard."] = "Караван заканчивает путь в лагере Smeed на восточной стороне Кладбища кодо.",
	["Scrabblescrew's Camp"] = "Лагерь Scrabblescrew",
	["Felgur Twocuts and Gurda Wildmane stand in the post just west of Smeed's camp."] = "Felgur Twocuts и Gurda Wildmane стоят на посту сразу к западу от лагеря Smeed.",
	["Ghost Walker Post"] = "Застава Призрачного Странника",
	["Head north up the road to the hut by the road north of the graveyard."] = "Идите на север по дороге к хижине у дороги к северу от кладбища.",
	["Kormek's Hut"] = "Хижина Kormek",
	["Pick up the kodo bones scattered across the graveyard."] = "Соберите кости кодо, разбросанные по кладбищу.",
	["Kodo bones"] = "Кости кодо",
	["The Burning Blade hold the fortress north-west of Kormek's Hut. Use the Demon Pick on the Demon Spirit in the fortress to get the Demon Box."] = "Пылающий Клинок удерживает крепость к северо-западу от хижины Kormek. Используйте Demon Pick на духе демона в крепости, чтобы получить Demon Box.",
	["Thunder Axe Fortress"] = "Крепость Громового Топора",
	["Head west to Azore Aldamort's tower at Ethel Rethor on the north-west coast."] = "Идите на запад к башне Azore Aldamort в Этель Ретор на северо-западном побережье.",
	["Ethel Rethor"] = "Этель Ретор",
	["The Slitherblade naga hold the coast north of Ethel Rethor, up to Sar'theris Strand. Lord Kragaru guards the Book of the Ancients at the far northern tip."] = "Наги Slitherblade держат побережье к северу от Этель Ретора, до берега Сар'терис. Lord Kragaru охраняет Book of the Ancients на самой северной оконечности.",
	["Slitherblade coast"] = "Побережье Slitherblade",
	["Azore Aldamort"] = "Azore Aldamort",
	["Head south from Ethel Rethor into the Valley of Spears. The Maraudine Scouts, Wranglers, Maulers, Windchasers and Marauders (36-39) drop the Carved Centaur Totems."] = "Идите на юг от Этель Ретора в Долину Копий. С разведчиков, укротителей, громил, ветроловов и мародёров Мародин (36-39) выпадают резные тотемы кентавров.",
	["Maraudine totems"] = "Тотемы Мародин",
	["Head on south-west to Shadowprey."] = "Идите дальше на юго-запад, в Деревню Теневой Охоты.",
	["Head east to Mannoroc Coven. Use the Rod of Banishing by each demon portal to close six of them."] = "Идите на восток к Ковену Маннорок. Используйте Rod of Banishing у демонических порталов, чтобы закрыть шесть из них.",
	["Portals of the Legion"] = "Порталы Легиона",
	["Head south-east from the coven to the bone fields of the Valley of Bones, where Undead Ravagers roam. At the far south-east, use the Crate of Ghost Magnets to draw the Magrami Spectres: they drop the ghost-o-plasm."] = "Идите на юго-восток от ковена к костяным полям Долины Костей, где бродят нежить-опустошители. В дальнем юго-восточном углу используйте Crate of Ghost Magnets, чтобы приманить призраков Magrami: с них выпадает призрачная плазма.",
	["The Valley of Bones"] = "Долина Костей",
	["Head north to Gurda Wildmane at Ghost Walker Post."] = "Идите на север к Gurda Wildmane на Заставе Призрачного Странника.",
	["Hornizz Brimbuzzle"] = "Hornizz Brimbuzzle",
	["Hearth to Shadowprey Village"] = "Камень возвращения — в Деревню Теневой Охоты",
	["The next guide takes you back to Stranglethorn Vale."] = "Следующий гид вернёт вас в Тернистую долину.",
	["Hearth to Shadowprey"] = "Камень возвращения — в Деревню Теневой Охоты",
	["Get the flight path at Brackenwall Village"] = "Возьмите точку полёта в деревне Бракенвол",
	["Mannoroc Coven"] = "Ковен Маннорок",
	["Stranglethorn Vale & Swamp of Sorrows"] = "Тернистая долина и Болото Печали",
	["From Shadowprey Village fly to Ratchet."] = "Из Деревни Теневой Охоты летите в Кабестан.",
	["The boat to Booty Bay docks at the end of Ratchet's pier."] = "Корабль в Пиратскую Бухту причаливает в конце пирса Кабестана.",
	["Boat to Booty Bay"] = "Корабль в Пиратскую Бухту",
	["The boat lands in Booty Bay's harbour. The quest givers stand on the boardwalks around the harbour and in the inn."] = "Корабль приходит в гавань Пиратской Бухты. Те, кто даёт задания, стоят на мостках вокруг гавани и в таверне.",
	["Leave town by the tunnel; the note lies in the pirates' cove just north of Booty Bay."] = "Выйдите из города через туннель; записка лежит в пиратской бухточке сразу к северу от Пиратской Бухты.",
	["Bloodsail Correspondence"] = "Переписка Кровавого Паруса",
	["South of Booty Bay the Bloodsail swashbucklers camp on the Wild Shore; the charts and the orders lie in their tents. Any Bloodsail can carry snuff and Dizzy's eye, so keep killing until you have both."] = "К югу от Пиратской Бухты головорезы Кровавого Паруса стоят лагерем на Диком берегу; карты и приказы — в их палатках. Табак и глаз для Dizzy может быть у любого пирата Кровавого Паруса, так что убивайте, пока не получите оба.",
	["The Wild Shore"] = "Дикий берег",
	["The three ships lie off the Wild Shore. The crews are 42-45, Stillwater 45, Keelhaul 46 and Fleet Master Firallon 48: at 41 this is a fight for a group, or for the end of the guide. If you go, swim out and pull the crew to the rail one at a time. A scroll, Cortello's Riddle, lies on the ships' decks: take it."] = "Три корабля стоят у Дикого берега. Команды — 42-45, Stillwater — 45, Keelhaul — 46, Fleet Master Firallon — 48: на 41 уровне это бой для группы или на конец гида. Если пойдёте, плывите туда и вытягивайте команду к борту по одному. На палубах лежит свиток Cortello's Riddle: возьмите его.",
	["The Bloodsail ships"] = "Корабли Кровавого Паруса",
	["Take the road north out of Booty Bay; Unbagwa sits on a hill in Mistvale Valley, east of the road."] = "Идите по дороге на север от Пиратской Бухты; Unbagwa сидит на холме в долине Mistvale, к востоку от дороги.",
	["Witch Doctor Unbagwa"] = "Witch Doctor Unbagwa",
	["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "Гориллы бродят по долине вокруг Unbagwa. Потроха выпадают со старых горилл, клык — с любой.",
	["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then Mokk. Fight them one at a time."] = "Отдайте Unbagwa клыки и стойте рядом: он призовёт три волны горилл, затем Mokk. Бейте их по одной.",
	["Mokk the Savage"] = "Mokk the Savage",
	["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "К северо-востоку от Mistvale в джунглях стоят лагерем последователи Zanzil; смесь может быть у любого из них.",
	["Zanzil's camps"] = "Лагеря Zanzil",
	["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "Дальше на север гоблины Торговой компании копают в шахте к востоку от дороги; кристаллы выпадают с шахтёров, бригадиров, разведчиков и механиков.",
	["Venture Co. mine"] = "Шахта Торговой компании",
	["Ride north-west to Grom'gol."] = "Езжайте на северо-запад в Гром'гол.",
	["Ride north up the road; the hunters camp on the hill above the river."] = "Езжайте на север по дороге; охотники стоят лагерем на холме над рекой.",
	["Nesingwary's Expedition"] = "Экспедиция Несингвари",
	["West of the expedition, the Bloodscalp chiefs Gan'zulah and Nezzliok stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "К западу от экспедиции вожди Кровавого Скальпа Gan'zulah и Nezzliok стоят вместе в руинах Зул'Кунды. Сначала перебейте охрану, потом тяните их.",
	["Zul'Kunda"] = "Зул'Кунда",
	["The stalker raptors hunt the jungle south of Grom'gol, out towards the west coast."] = "Ящеры-охотники рыщут по джунглям к югу от Гром'гола, в сторону западного побережья.",
	["Jungle stalkers"] = "Ящеры Jungle Stalker",
	["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the Holy Spring bubbles in the hills just east of them."] = "Идите по побережью на юг. Наги-исследователи бродят по мелководью и несут связки тростника; Святой источник бьёт в холмах сразу к востоку от них.",
	["Naga shore and the Holy Spring"] = "Берег наг и Святой источник",
	["Ride south to Booty Bay. Shaky Phillipe waits on the docks."] = "Езжайте на юг в Пиратскую Бухту. Shaky Phillipe ждёт на пристани.",
	["Kill Maury \"Club Foot\" Wilkins"] = "Убейте Maury \"Club Foot\" Wilkins",
	["Kill Jon-Jon the Crow"] = "Убейте Jon-Jon the Crow",
	["Kill Chucky \"Ten Thumbs\""] = "Убейте Chucky \"Ten Thumbs\"",
	["The three ghostly pirates haunt the jungle north of Booty Bay, near Zanzil's camps: Maury and Jon-Jon stand together, Chucky further east."] = "Три пирата-призрака бродят в джунглях к северу от Пиратской Бухты, у лагерей Zanzil: Maury и Jon-Jon стоят вместе, Chucky — восточнее.",
	["Pirate ghosts"] = "Пираты-призраки",
	["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. Ana'thek the Cruel guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "Езжайте на север к руинам Skullsplitter к востоку от шахты Торговой компании; тяните охотников за головами и берсерков по одному. Ana'thek the Cruel охраняет юго-западные руины, а одна груда черепов-трофеев стоит на северной стороне руин. С любого Skullsplitter может выпасть клык или ожерелье: ожерелья — самое долгое, так что бейте в лагере воинов к северу от руин, пока не соберёте все.",
	["Zul'Mamwe"] = "Зул'Мамве",
	["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "Следующие черепа-трофеи стоят в маленьких руинах сразу к северу от лагеря воинов.",
	["Balia'mah Ruins"] = "Руины Балиа'ма",
	["The last skulls are in the ruins a short ride west, on the way back to Grom'gol."] = "Последние черепа — в руинах немного западнее, по пути обратно в Гром'гол.",
	["Ziata'jai Ruins"] = "Руины Зиата'джай",
	["Ride west to Grom'gol."] = "Езжайте на запад в Гром'гол.",
	["Ride north up the road to the hunters' camp."] = "Езжайте на север по дороге к лагерю охотников.",
	["Keep riding north into Duskwood, then east along the road through Deadwind Pass into the swamp. Magtoor waits at the Harborage, the draenei camp near the way in from Deadwind Pass."] = "Езжайте дальше на север в Сумеречный лес, затем на восток по дороге через Перевал Мертвого Ветра в болото. Magtoor ждёт в Пристанище — лагере дренеев у входа со стороны Перевала Мертвого Ветра.",
	["Into the Swamp of Sorrows"] = "В Болото Печали",
	["Ride east to Stonard, in the reeds south of the road."] = "Езжайте на восток в Каменор, в камышах к югу от дороги.",
	["Stonard"] = "Каменор",
	["Ride north-east to the Fallow Sanctuary. The crystals stand along the way up to Galen Goodward's cage."] = "Езжайте на северо-восток к Заброшенному святилищу. Кристаллы стоят вдоль пути наверх, к клетке Galen Goodward.",
	["Draenethyst crystals"] = "Кристаллы дренетиста",
	["Galen Goodward is held in the Fallow Sanctuary in the swamp's north-east. Free him and follow him out, fighting off the swamp creatures that chase him."] = "Galen Goodward в плену в Заброшенном святилище на северо-востоке болота. Освободите его и идите за ним, отбиваясь от болотных тварей, что гонятся за ним.",
	["Galen's Escape"] = "Побег Galen",
	["Kill Noboru the Cudgel"] = "Убейте Noboru the Cudgel",
	["Noboru wanders the clearing south-west of the Fallow Sanctuary; his cudgel starts a quest."] = "Noboru бродит по поляне к юго-западу от Заброшенного святилища; его дубинка начинает задание.",
	["Noboru the Cudgel"] = "Noboru the Cudgel",
	["His strongbox waits at his old camp north of Stonard."] = "Его сундук ждёт в старом лагере к северу от Каменора.",
	["Galen's Strongbox"] = "Сундук Galen",
	["The crocolisks wallow in the pools around Galen's camp and south towards Stonard; about one in four drops a flank."] = "Кроколиски валяются в лужах вокруг лагеря Galen и южнее, к Каменору; бок выпадает примерно с каждого четвёртого.",
	["Sawtooth crocolisks"] = "Пилозубые кроколиски",
	["Ride west along the road to the draenei camp at the Harborage, near the way in from Deadwind Pass."] = "Езжайте на запад по дороге к лагерю дренеев в Пристанище, у входа со стороны Перевала Мертвого Ветра.",
	["The Harborage"] = "Пристанище",
	["Ride back east past Stonard and follow the road south-east to the small Horde post on the shore."] = "Возвращайтесь на восток мимо Каменора и по дороге на юго-восток к маленькой заставе Орды на берегу.",
	["Misty Reed Post"] = "Застава Туманного Тростника",
	["The snappers line the strand south of the post."] = "Черепахи-щелкуны усеивают берег к югу от заставы.",
	["Sawtooth snappers"] = "Пилозубые щелкуны",
	["The next guide starts here and takes you to Tanaris."] = "Следующий гид начинается здесь и ведёт в Танарис.",
	["Ratchet pier"] = "Пирс Кабестана",
	["Skullsplitter warriors"] = "Воины Skullsplitter",
	["Get the flight path at Stonard"] = "Возьмите точку полёта в Каменоре",
	["Feralas & Tanaris"] = "Фералас и Танарис",
	["Ride back north-west from Misty Reed Post to Stonard and fly to Grom'gol."] = "Езжайте обратно на северо-запад от Заставы Туманного Тростника в Каменор и летите в Гром'гол.",
	["The Orgrimmar zeppelin leaves from the tower beside Grom'gol; it lands just outside Orgrimmar's main gate."] = "Дирижабль в Оргриммар отправляется с башни рядом с Гром'голом; он причаливает прямо у главных ворот Оргриммара.",
	["Kildar, riding trainer"] = "Kildar, учитель верховой езды",
	["Wolves: Ogunaro Wolfrunner, beside Kildar."] = "Волки: Ogunaro Wolfrunner, рядом с Kildar.",
	["Galestriders: Genn Fairweather, in Valanaar on Zephras Isle."] = "Ветроходы: Genn Fairweather, в Валанааре на острове Зефрас.",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. Kildar teaches Orcs in the Valley of Honor, by Ogunaro Wolfrunner's kennel; no Skyborne riding trainer is known, so Skyborne try Kildar too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "Верховая езда требует 40 уровня и стоит 100 золотых; при обучении вы получаете ездовое животное. Kildar учит орков в Аллее Чести, у псарни Ogunaro Wolfrunner; учитель верховой езды для небеснорождённых неизвестен, так что им тоже стоит попробовать Kildar. Другие ездовые животные вашей расы — по 20 золотых: в разделе «Коллекции», «Ездовые животные · уровень 40» есть гид для каждого.",
	["Riding at 40"] = "Верховая езда на 40",
	["Xar'Ti, riding trainer"] = "Xar'Ti, учитель верховой езды",
	["Raptors: Zjolnir, beside Xar'Ti in Sen'jin Village."] = "Ящеры: Zjolnir, рядом с Xar'Ti в деревне Сен'джин.",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is Xar'Ti in Sen'jin Village on the Durotar coast, with Zjolnir's raptors (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try Kildar in Orgrimmar's Valley of Honor first, as he is the nearest, and skip this step if he teaches you."] = "Верховая езда требует 40 уровня и стоит 100 золотых; при обучении вы получаете ездовое животное. В Classic каждая раса учится у своего учителя: ваш — Xar'Ti в деревне Сен'джин на побережье Дуротара, рядом ящеры Zjolnir (по 20 золотых). В Forever, возможно, любая раса может учиться у любого учителя (не подтверждено): сначала попробуйте Kildar в Аллее Чести Оргриммара — он ближе всех; если он вас обучит, пропустите этот шаг.",
	["Kar Stormsinger, riding trainer"] = "Kar Stormsinger, учитель верховой езды",
	["Kodos: Harb Clawhoof, beside Kar Stormsinger in Bloodhoof Village."] = "Кодо: Harb Clawhoof, рядом с Kar Stormsinger в деревне Кровавого Копыта.",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is Kar Stormsinger in Bloodhoof Village, with Harb Clawhoof's kodos (20 gold each) beside him. Forever may let any race learn from any riding trainer (not confirmed): try Kildar in Orgrimmar's Valley of Honor first, as he is the nearest, and skip this step if he teaches you."] = "Верховая езда требует 40 уровня и стоит 100 золотых; при обучении вы получаете ездовое животное. В Classic каждая раса учится у своего учителя: ваш — Kar Stormsinger в деревне Кровавого Копыта, рядом кодо Harb Clawhoof (по 20 золотых). В Forever, возможно, любая раса может учиться у любого учителя (не подтверждено): сначала попробуйте Kildar в Аллее Чести Оргриммара — он ближе всех; если он вас обучит, пропустите этот шаг.",
	["Velma Warnam, riding trainer"] = "Velma Warnam, учитель верховой езды",
	["Skeletal horses: Zachariah Post, beside Velma Warnam in Brill."] = "Скелеты коней: Zachariah Post, рядом с Velma Warnam в Брилле.",
	["Riding needs level 40 and costs 100 gold; learning it gives you a mount. In Classic each race learns it from its own race's trainer: yours is Velma Warnam in Brill, with Zachariah Post's skeletal horses (20 gold each) beside her. Forever may let any race learn from any riding trainer (not confirmed): try Kildar in Orgrimmar's Valley of Honor first, as he is the nearest, and skip this step if he teaches you."] = "Верховая езда требует 40 уровня и стоит 100 золотых; при обучении вы получаете ездовое животное. В Classic каждая раса учится у своего учителя: ваш — Velma Warnam в Брилле, рядом скелеты коней Zachariah Post (по 20 золотых). В Forever, возможно, любая раса может учиться у любого учителя (не подтверждено): сначала попробуйте Kildar в Аллее Чести Оргриммара — он ближе всех; если он вас обучит, пропустите этот шаг.",
	["Your trainer is in Thunder Bluff: Turak Runetotem (Druids) on Elder Rise, Alodan the Hopeful (Paladins). Fly there from Orgrimmar, then on to Freewind Post."] = "Ваш учитель — в Громовом Утесе: Turak Runetotem (друиды) на Вершине Старейшин, Alodan the Hopeful (паладины). Летите туда из Оргриммара, потом дальше в Лагерь Вольного Ветра.",
	["Ratchet for the Felsteed"] = "Кабестан — за конём Скверны",
	["Fly to Freewind Post"] = "Летите в Лагерь Вольного Ветра",
	["Fly to Freewind Post, ride down the lift east of the post and across the salt flats, then south into Tanaris."] = "Летите в Лагерь Вольного Ветра, спуститесь на лифте к востоку от лагеря, пересеките солончаки и идите на юг в Танарис.",
	["Gadgetzan is the walled goblin town just past the Tanaris border."] = "Прибамбасск — гоблинский город за стенами сразу за границей Танариса.",
	["Gadgetzan"] = "Прибамбасск",
	["water pouches in your bags"] = "бурдюки с водой в сумках",
	["The bandits and thieves camp in the dunes east of Gadgetzan. Every Wastewander can carry a water pouch: keep ten, five for each of Luglunket's bounties."] = "Бандиты и воры стоят лагерями в дюнах к востоку от Прибамбасска. Бурдюк с водой может быть у любого Wastewander: сохраните десять — по пять на каждую награду Luglunket.",
	["Eastern Wastewander camps"] = "Восточные лагеря Wastewander",
	["The shadow mages, rogues and assassins camp south-east of Gadgetzan."] = "Маги тьмы, разбойники и убийцы стоят лагерем к юго-востоку от Прибамбасска.",
	["Southern Wastewander camps"] = "Южные лагеря Wastewander",
	["Ride north-east to the goblin harbour on the coast."] = "Езжайте на северо-восток к гоблинской гавани на побережье.",
	["Steamwheedle Port"] = "Порт Картеля",
	["South along the coast, the Southsea pirates hold the cove. Andre Firebeard and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "Южнее вдоль побережья пираты Южных морей держат бухту. Andre Firebeard и украденный груз — на пристани в её дальнем конце. Шляпа может выпасть с любого пирата, чаще всего с похитителей.",
	["Lost Rigger Cove"] = "Бухта Пропавшего Такелажника",
	["Ride back west to Gadgetzan."] = "Езжайте обратно на запад в Прибамбасск.",
	["Fly to Freewind Post, then ride west through the canyons past Whitereach Post; the road climbs into the Feralas jungle and on to Camp Mojache."] = "Летите в Лагерь Вольного Ветра, затем езжайте на запад через каньоны мимо Заставы Белого Берега; дорога поднимается в джунгли Фераласа и ведёт к Лагерю Мохаче.",
	["Camp Mojache"] = "Лагерь Мохаче",
	["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "Гноллы Woodpaw стоят лагерем на холмах сразу к северо-западу от Мохаче; грива может выпасть с любого.",
	["Woodpaw north camp"] = "Северный лагерь Woodpaw",
	["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "К северу от гноллов огры держат заставу на холме; подтягивайте огров-магов к себе. Кобальт — в земляных кучах вокруг заставы, а свиток лежит на земле внутри.",
	["Gordunni Outpost"] = "Застава Гордунни",
	["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "Феи-стрекозы порхают над рощей сразу к западу от Мохаче; крыло выпадает почти с каждой. Вожаки Woodpaw ведут лагеря к юго-западу от неё: убейте их в течение часа.",
	["Sprite darters and Woodpaw alphas"] = "Феи-стрекозы и вожаки Woodpaw",
	["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "Таурены Зловещего Тотема стоят лагерем рядом с рощей фей; рога есть у налётчиков, натуралистов и шаманов.",
	["Grimtotem camp"] = "Лагерь Зловещего Тотема",
	["The battle map lies in the Woodpaw camp south of Mojache."] = "Боевая карта лежит в лагере Woodpaw к югу от Мохаче.",
	["Woodpaw battle map"] = "Боевая карта Woodpaw",
	["Ride south-west to the ogre ruins below Feral Scar Vale. Shamans, warlocks and maulers fill them; the Mage-Lords at the southern end carry the orb."] = "Езжайте на юго-запад к руинам огров под Долиной Дикого Шрама. Там шаманы, чернокнижники и громилы; сферу носят маги-лорды в южной части.",
	["Southern Gordunni ruins"] = "Южные руины Гордунни",
	["The Zukk'ash hive burrows into the hills south-east of the camp; Stinglasher waits in its deepest chamber."] = "Улей Зукк'аш уходит в холмы к юго-востоку от лагеря; Stinglasher ждёт в самом глубоком зале.",
	["The Writhing Deep"] = "Корчащиеся глубины",
	["Use Yeh'kinya's Bramble"] = "Используйте Yeh'kinya's Bramble",
	["Ride west into the middle of Feralas. Kill a Rogue Vale Screecher, use Yeh'kinya's Bramble on its body and kill the spirit that rises."] = "Езжайте на запад в центр Фераласа. Убейте Rogue Vale Screecher, используйте Yeh'kinya's Bramble на его теле и убейте поднявшегося духа.",
	["Rogue Vale screechers"] = "Крикуны Rogue Vale",
	["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "Езжайте дальше на запад к побережью. С Coast Crawl Deepseer и Snapclaw на пляжах примерно один раз из сорока выпадает аварийный маяк OOX-22/FE: если выпал, используйте его, чтобы начать задание.",
	["The Forgotten Coast"] = "Забытый берег",
	["Only with the distress beacon: the robot sits in a small cave on the north side of Feral Scar Vale. Escort it to the dock on the Forgotten Coast; yetis and gorillas ambush you on the way. Its reward waits in Booty Bay for a later visit."] = "Только если есть аварийный маяк: робот сидит в маленькой пещере на северной стороне Долины Дикого Шрама. Сопроводите его к пристани на Забытом берегу; по пути нападут йети и гориллы. Награда будет ждать в Пиратской Бухте, заберёте позже.",
	["Homing Robot OOX-22/FE"] = "Робот OOX-22/FE",
	["Hearth to Camp Mojache"] = "Камень возвращения — в Лагерь Мохаче",
	["Fly to Orgrimmar"] = "Летите в Оргриммар",
	["Fly to Orgrimmar. The Droffers brothers run their shop in the Drag."] = "Летите в Оргриммар. Братья Droffers держат лавку на Аллее Силы.",
	["The Grom'gol zeppelin leaves from the tower just north-east of Orgrimmar's main gate."] = "Дирижабль в Гром'гол отправляется с башни сразу к северо-востоку от главных ворот Оргриммара.",
	["Fly to Stonard"] = "Летите в Каменор",
	["Thysta, the flight master, stands just east of the zeppelin tower. Fly to Stonard: the next guide starts there."] = "Thysta, распорядитель полётов, стоит сразу к востоку от башни дирижаблей. Летите в Каменор: следующий гид начинается там.",
	["Get the flight path at Gadgetzan"] = "Возьмите точку полёта в Прибамбасске",
	["Get the flight path at Camp Mojache"] = "Возьмите точку полёта в Лагере Мохаче",
	["Feralas, Dustwallow Marsh & Swamp of Sorrows"] = "Фералас, Пылевые топи и Болото Печали",
	["You start in Stonard. Bind here: you hearth back after the coast."] = "Вы начинаете в Каменоре. Привяжите камень здесь: после побережья вернётесь сюда.",
	["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "Езжайте на запад по дороге; свиток лежит у кромки воды на дальнем западе болота.",
	["A Soggy Scroll"] = "Размокший свиток",
	["Back east past Stonard: the Atal'ai artifacts lie in the water and on the banks of the Pool of Tears."] = "Обратно на восток мимо Каменора: артефакты Атал'ай лежат в воде и на берегах Пруда Слёз.",
	["Pool of Tears"] = "Пруд Слёз",
	["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "Чудовищные ползуны бродят по пляжам восточного побережья, их мало и они далеко друг от друга: убивайте каждого, кого встретите по пути на юг.",
	["Monstrous Crawlers"] = "Чудовищные ползуны",
	["The small Horde post on the southern shore."] = "Небольшая застава Орды на южном берегу.",
	["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "Болотные мурлоки живут на берегу к югу от заставы; чернильные — вдоль берега к востоку от неё, а мясоеды — западнее, у хижин на западном берегу.",
	["Murlocs of the Misty Reed"] = "Мурлоки Туманного Тростника",
	["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "Те же мурлоки снова, плюс оракулы, которые держатся у хижин на западном берегу.",
	["Continued Threat"] = "Угроза не миновала",
	["Hearth to Stonard"] = "Камень возвращения — в Каменор",
	["The zeppelin to Orgrimmar leaves from the tower beside Grom'gol; it lands just north-east of Orgrimmar's main gate."] = "Дирижабль в Оргриммар отправляется с башни рядом с Гром'голом; он причаливает сразу к северо-востоку от главных ворот Оргриммара.",
	["Valley of Honor, then the Cleft of Shadow and the Valley of Spirits."] = "Аллея Чести, затем Расселина Теней и Аллея Духов.",
	["Your trainer is in Thunder Bluff: fly there (no flight path there yet? fly to Camp Taurajo and ride west through Mulgore), then on to Brackenwall Village."] = "Ваш учитель — в Громовом Утесе: летите туда (точки полёта там ещё нет? летите в Лагерь Таурахо и езжайте на запад через Мулгор), потом дальше в деревню Бракенвол.",
	["Fly to Brackenwall Village"] = "Летите в деревню Бракенвол",
	["Ride south-west to the Musty Scroll, then east through the Wyrmbog. The Firemane scouts and ash tails roam its northern edge with the Searing hatchlings and whelps; the scalebanes guard the dragon caves further south-east. Mok'Morokk's snuff, grog and strongbox lie in the dragonkin camps."] = "Езжайте на юго-запад к Затхлому свитку, затем на восток через Драконью топь. Разведчики и пеплохвосты Firemane бродят по её северному краю вместе с детёнышами и дракончиками Searing; scalebane охраняют драконьи пещеры дальше на юго-востоке. Табак, грог и сундук Mok'Morokk лежат в лагерях драконидов.",
	["The Wyrmbog"] = "Драконья топь",
	["Ride back north to Brackenwall."] = "Езжайте обратно на север в Бракенвол.",
	["The Eggs of Onyxia lie in the dragon caves in the Wyrmbog's south-east, guarded by the scalebanes; smash five."] = "Яйца Ониксии лежат в драконьих пещерах на юго-востоке Драконьей топи под охраной scalebane; разбейте пять.",
	["Onyxia's eggs"] = "Яйца Ониксии",
	["Overlord Mok'Morokk is elite: grouping up is advised. Beat him down until he gives up, then report to Draz'Zilb."] = "Overlord Mok'Morokk — элитный: лучше собрать группу. Бейте его, пока он не сдастся, затем доложите Draz'Zilb.",
	["Challenge Overlord Mok'Morokk"] = "Вызов Overlord Mok'Morokk",
	["Fly to Camp Mojache"] = "Летите в Лагерь Мохаче",
	["The sprite darters flit over the grove just west of the camp and carry the Encrusted Minerals; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "Феи-стрекозы порхают над рощей сразу к западу от лагеря и несут Encrusted Minerals; бродячие лесные ходоки чуть западнее несут Splintered Logs.",
	["Sprite darters and forest walkers"] = "Феи-стрекозы и лесные ходоки",
	["South-west, the yetis den in Feral Scar Vale; every yeti there can drop a thick hide."] = "На юго-западе йети живут в Долине Дикого Шрама; с любого йети там может выпасть толстая шкура.",
	["Feral Scar Vale"] = "Долина Дикого Шрама",
	["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "К югу от долины на склонах гнездятся гиппогрифы Frayfeather; почти с каждого выпадают сухожилия и металлические осколки.",
	["Frayfeather hippogryphs"] = "Гиппогрифы Frayfeather",
	["Ride north-west to the Forgotten Coast; Zorbin waits on the dock."] = "Езжайте на северо-запад к Забытому берегу; Zorbin ждёт на пристани.",
	["Zorbin Fandazzle"] = "Zorbin Fandazzle",
	["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with Zorbin's Ultra-Shrinker first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "Морские элементали и морские брызги ходят по берегу у пристани. Сначала уменьшите великанов с помощью Zorbin's Ultra-Shrinker: уменьшенные, они теряют силу элитных. Береговые странники бродят по воде; сухопутные ходоки и утёсные великаны — на холмах севернее.",
	["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "Гарпии Northspring гнездятся на гребнях на дальнем северо-западе. Они 48-50, на несколько уровней выше вас: заклинательницы ветра лечат, так что убивайте их первыми и тяните по одной.",
	["Northspring harpies"] = "Гарпии Northspring",
	["Perfect Yeti Hide, a rare drop"] = "Perfect Yeti Hide, редкая добыча",
	["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a Perfect Yeti Hide, which starts a quest of its own."] = "На северо-запад по дороге йети Rage Scar живут у пещер в холмах. С любого из них может выпасть Perfect Yeti Hide — она начинает отдельное задание.",
	["Rage Scar yetis"] = "Йети Rage Scar",
	["Ride back east to the camp. Stay here: the next guide starts with the flight to Gadgetzan."] = "Езжайте обратно на восток в лагерь. Оставайтесь здесь: следующий гид начинается с перелёта в Прибамбасск.",
	["Get the flight path at Thunder Bluff"] = "Возьмите точку полёта в Громовом Утесе",
	["Dragon caves"] = "Драконьи пещеры",
	["Forest walkers"] = "Лесные ходоки",
	["Tanaris & Searing Gorge"] = "Танарис и Тлеющее ущелье",
	["Fly to Gadgetzan"] = "Летите в Прибамбасск",
	["From Camp Mojache's flight master."] = "У распорядителя полётов Лагеря Мохаче.",
	["West of Gadgetzan, use the Untapped Dowsing Widget beside the water hole in the troll camp."] = "К западу от Прибамбасска используйте Untapped Dowsing Widget у водоёма в лагере троллей.",
	["Sandsorrow Watch"] = "Дозор Скорбных Песков",
	["South-east of Gadgetzan the Wastewander bandits camp in the dunes; Caliph stands in the eastern camp."] = "К юго-востоку от Прибамбасска бандиты Wastewander стоят лагерями в дюнах; Caliph — в восточном лагере.",
	["Caliph Scorpidsting"] = "Caliph Scorpidsting",
	["West along the road south; Marvon camps by the ruins at the Broken Pillar. Put on his Gahz'ridian Detector: it shows the buried ornaments, here and around the Dunemaul Compound."] = "На запад по южной дороге; Marvon стоит лагерем у руин Сломанной колонны. Наденьте его Gahz'ridian Detector: он показывает закопанные украшения — здесь и вокруг Поселения Дюнного Молота.",
	["Marvon Rivetseeker"] = "Marvon Rivetseeker",
	["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "На западе насекомые Centipaar роятся вокруг ульев; детали выпадают с любого.",
	["The Noxious Lair"] = "Ядовитое логово",
	["South of the Noxious Lair the Dunemaul ogres hold their compound, with Gor'marok the Ravager at its eastern end. Dig up Gahz'ridian ornaments between the fights."] = "К югу от Ядовитого логова огры Дюнного Молота держат своё поселение, Gor'marok the Ravager — в восточной части. Между боями выкапывайте украшения Gahz'ridian.",
	["Dunemaul Compound"] = "Поселение Дюнного Молота",
	["OOX-17/TN Distress Beacon, a rare drop"] = "OOX-17/TN Distress Beacon, редкая добыча",
	["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in Tanaris can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "К западу от поселения долину заполняют кактусовые существа; железа росы есть только у сборщиков росы. С большинства существ Танариса изредка выпадает аварийный маяк OOX-17/TN: если увидите, сохраните.",
	["Thistleshrub Valley"] = "Долина Колючих Кустов",
	["Tooga waits in the valley. Walk him all the way to his wife Torta in Steamwheedle Port, north-east across the desert: stay close, slow down for him and fight off what attacks him. Do not mount or hearth out of his reach. Yeh'kinya stands in the port too."] = "Tooga ждёт в долине. Ведите его до самой жены Torta в Порт Картеля, на северо-восток через пустыню: держитесь рядом, не убегайте вперёд и отбивайтесь от нападающих. Не садитесь на маунта и не используйте камень возвращения, пока он далеко. Yeh'kinya тоже стоит в порту.",
	["Tooga's escort"] = "Сопровождение Tooga",
	["Ride south-west to Gadgetzan."] = "Езжайте на юго-запад в Прибамбасск.",
	["South down the road again."] = "Снова на юг по дороге.",
	["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "Ещё южнее снаряжение младшего разведчика Scrimshank лежит у входа в улей Centipaar.",
	["Scrimshank's gear"] = "Снаряжение Scrimshank",
	["Only with the distress beacon: OOX-17/TN sits south-east of Scrimshank's hive. Escort it north to Steamwheedle Port; its reward waits with Oglethorpe in Booty Bay."] = "Только если есть аварийный маяк: OOX-17/TN сидит к юго-востоку от улья Scrimshank. Сопроводите его на север в Порт Картеля; награда ждёт у Oglethorpe в Пиратской Бухте.",
	["OOX-17/TN"] = "OOX-17/TN",
	["Hearth to Gadgetzan"] = "Камень возвращения — в Прибамбасск",
	["Fly to Orgrimmar and train: the next guide's training stop is the Undercity, which has no Hunter or Shaman trainer. Then fly to Ratchet."] = "Летите в Оргриммар и потренируйтесь: в следующем гиде учителя будут в Подгороде, а там нет учителей охотников и шаманов. Затем летите в Кабестан.",
	["Fly to Thunder Bluff and train with Turak Runetotem on Elder Rise, then fly to Ratchet."] = "Летите в Громовой Утес и потренируйтесь у Turak Runetotem на Вершине Старейшин, затем летите в Кабестан.",
	["The boat to Booty Bay docks at Ratchet's pier, below the flight master's hill."] = "Корабль в Пиратскую Бухту причаливает к пирсу Кабестана, под холмом распорядителя полётов.",
	["Fly to Kargath"] = "Летите в Каргат",
	["From the Booty Bay flight master, above the harbour."] = "У распорядителя полётов Пиратской Бухты, над гаванью.",
	["Take the pass out of Kargath's west side into the Searing Gorge, then ride south-west to the dig site. The Wooden Outhouse stands at its southern end; the Dark Iron Geologists dig just north of it. Bring 15 Silk Cloth (the Auction House sells it)."] = "Пройдите через перевал с западной стороны Каргата в Тлеющее ущелье, затем езжайте на юго-запад к раскопкам. Деревянный сортир стоит в южной части; геологи Черного Железа копают сразу к северу от него. Возьмите 15 шёлка (можно купить на аукционе).",
	["The Grimesilt Dig Site"] = "Раскопки Грязного Ила",
	["Ride north-west across the gorge; Thorium Point is the scaffolded camp in the north-west."] = "Езжайте на северо-запад через ущелье; Торианская Твердыня — лагерь в лесах на северо-западе.",
	["Thorium Point"] = "Торианская Твердыня",
	["Kalaran stands alone south of Thorium Point, at the edge of the Cauldron. Listen to his story."] = "Kalaran стоит один к югу от Торианской Твердыни, на краю Котла. Выслушайте его историю.",
	["Kalaran Windblade"] = "Kalaran Windblade",
	["Grimesilt Outhouse Key, a rare drop"] = "Grimesilt Outhouse Key, редкая добыча",
	["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the Grimesilt Outhouse Key: keep it."] = "Тяжёлые боевые големы патрулируют Котёл под Kalaran и роняют масло; с элементалей магмы и пылающих элементалей среди них выпадают сердца. Надсмотрщики и работорговцы Черного Железа гоняют рабов по тропам; с работорговца может выпасть Grimesilt Outhouse Key: сохраните его.",
	["The Cauldron"] = "Котёл",
	["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a Thorium Plated Dagger, one in ten the Smithing Tuyere. Slaves, Slavers and Taskmasters carry daggers too."] = "Паровые кузнецы Черного Железа работают у горнов посреди Котла; у половины есть Thorium Plated Dagger, у одного из десяти — Smithing Tuyere. Кинжалы есть и у рабов, работорговцев и надсмотрщиков.",
	["The Steamsmiths' furnaces"] = "Горны паровых кузнецов",
	["His next request needs the Symbol of Ragnaros from elite cultists: leave it."] = "Следующая просьба требует Symbol of Ragnaros с элитных культистов: пропустите.",
	["The Slag Pit opens in the north of the Cauldron. Incendosaurs swim in its lava pools: pull them to the edge. The secret plans lie on the pit's upper ledge."] = "Шлаковая яма открывается на севере Котла. Инсендозавры плавают в её лавовых озёрах: подтягивайте их к краю. Секретные планы лежат на верхнем уступе ямы.",
	["The Slag Pit"] = "Шлаковая яма",
	["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "Большие лавовые пауки бродят по плато и лавовым озёрам на юго-западе ущелья.",
	["Greater Lava Spiders"] = "Большие лавовые пауки",
	["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the Lookout's Spyglass."] = "Дозорные Черного Железа стоят на гребнях вокруг сторожевых башен к югу от Котла; примерно у одного из десяти есть Lookout's Spyglass.",
	["Dark Iron Lookouts"] = "Дозорные Черного Железа",
	["Only with the Grimesilt Outhouse Key: back east to the Wooden Outhouse at the dig site."] = "Только если есть Grimesilt Outhouse Key: обратно на восток к деревянному сортиру на раскопках.",
	["The Key to Freedom"] = "Ключ к свободе",
	["Ride back north to Thorium Point. Stay here: the next guide starts with the flight to Stonard."] = "Езжайте обратно на север в Торианскую Твердыню. Оставайтесь здесь: следующий гид начинается с перелёта в Каменор.",
	["Get the flight path at Thorium Point"] = "Возьмите точку полёта в Торианской Твердыне",
	["The Hinterlands & Blasted Lands"] = "Внутренние земли и Выжженные земли",
	["From Thorium Point's flight master."] = "У распорядителя полётов Торианской Твердыни.",
	["Ride west out of Stonard and south through the canyon into the Blasted Lands; the two bloodmages stand by the road just inside."] = "Езжайте на запад из Каменора и на юг через каньон в Выжженные земли; два мага крови стоят у дороги сразу за входом.",
	["The bloodmages"] = "Маги крови",
	["The five quests share the same parts: gather them all in one sweep. West of the road the Black Slayer vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "Пять заданий требуют одних и тех же частей: соберите всё за один заход. К западу от дороги на холмах живут грифы Black Slayer, голодные Snickerfang, жалящие скорпоки и василиски Deatheye.",
	["The northern beasts"] = "Северные звери",
	["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "К востоку от дороги кабаны Ashmane и Grunter роются на склонах рядом с василисками Redstone. Держитесь подальше от кабанов Скверны 52 уровня южнее.",
	["The eastern slopes"] = "Восточные склоны",
	["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "Продолжения просят те же части ещё раз ради предмета-усиления и не дают опыта: пропустите их.",
	["Ride back north to the bloodmages."] = "Езжайте обратно на север к магам крови.",
	["Only if you are not level 48 yet."] = "Только если у вас ещё нет 48 уровня.",
	["Grind to 48"] = "Докачайтесь до 48",
	["Fly to Undercity"] = "Летите в Подгород",
	["Ride north back to Stonard and fly to the Undercity."] = "Езжайте обратно на север в Каменор и летите в Подгород.",
	["Fly to the Undercity"] = "Летите в Подгород",
	["Undercity"] = "Подгород",
	["Ride north-east from Tarren Mill into the Hinterlands and east along the road; Gilveradin Sunchaser camps on the hill south of the elves' Quel'Danil Lodge."] = "Езжайте на северо-восток от Мельницы Таррен во Внутренние земли и на восток по дороге; Gilveradin Sunchaser стоит лагерем на холме к югу от эльфийской Сторожки Кель'Данил.",
	["Gilveradin's camp"] = "Лагерь Gilveradin",
	["The Highvale elves camp around Quel'Danil Lodge. Burn the report, the notes and the records in their camps. Rin'ji is held inside the lodge: lead him out and fight off the ambush on the way."] = "Эльфы Highvale стоят лагерями вокруг Сторожки Кель'Данил. Сожгите отчёт, заметки и записи в их лагерях. Rin'ji держат внутри сторожки: выведите его и отбейтесь от засады по пути.",
	["Highvale"] = "Highvale",
	["Use Nimboya's Pike"] = "Используйте Nimboya's Pike",
	["Use Nimboya's Laden Pike"] = "Используйте Nimboya's Laden Pike",
	["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use Nimboya's Pike to make the Laden Pike, then plant it inside the village."] = "К югу от сторожки тролли Witherbark удерживают свои деревни. У каждого есть череп: с двадцатью используйте Nimboya's Pike, чтобы сделать Laden Pike, затем установите его в деревне.",
	["Grim Message"] = "Мрачное послание",
	["East of the village, the violet flower grows in the hills."] = "К востоку от деревни в холмах растёт фиолетовый цветок.",
	["Violet Tragan"] = "Фиолетовый траган",
	["South-west again, the exile hides by the ruins of Shadra'Alor."] = "Снова на юго-запад: изгнанник прячется у руин Шадра'Алора.",
	["The Atal'ai Exile"] = "Изгнанник Атал'ай",
	["Follow the roads east across the Hinterlands to the troll village on the eastern coast."] = "Идите по дорогам на восток через Внутренние земли к деревне троллей на восточном побережье.",
	["Revantusk Village"] = "Деревня Сломанного Клыка",
	["OOX-09/HL Distress Beacon, a rare drop"] = "OOX-09/HL Distress Beacon, редкая добыча",
	["The big turtles crawl along the beaches north of the village. Whiskey Slim's port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "Большие черепахи ползают по пляжам к северу от деревни. Бутылки портвейна Whiskey Slim тоже лежат на этих пляжах, но его задания нет в этом маршруте. С черепахи изредка выпадает аварийный маяк OOX-09/HL: сохраните его.",
	["Saltwater Snapjaws"] = "Морские черепахи Snapjaw",
	["The secret lies on the Overlook Cliffs, above the beach."] = "Тайник лежит на Обзорных утёсах над пляжем.",
	["Rin'ji's Secret"] = "Секрет Rin'ji",
	["North along the coast, Lard's picnic basket is on the small island; a Vilebranch Kidnapper guards it."] = "Севернее вдоль побережья корзина для пикника Lard — на маленьком острове; её охраняет похититель Vilebranch.",
	["Lard's lunch"] = "Обед Lard",
	["West of the island, the Vilebranch scalpers hold the temples of Agol'watha and Shaol'watha. Slagtree's tools lie at one of the temples."] = "К западу от острова скальпировщики Vilebranch удерживают храмы Агол'вата и Шаол'вата. Инструменты Slagtree лежат у одного из храмов.",
	["The Vilebranch temples"] = "Храмы Vilebranch",
	["The Silvermane Stalkers, Savage Owlbeasts and Razorbeak Skylords share the hills between the temples and Skulk Rock. Use the Wildkin Muisek Vessel on the owlbeasts you kill. The Skylords also drop Long Elegant Feathers: keep ten for Otho's second message."] = "Ловчие Silvermane, дикие совухи и клювы-повелители неба Razorbeak делят холмы между храмами и Скалой Сокрытия. Используйте Wildkin Muisek Vessel на убитых совухах. С повелителей неба также выпадают Long Elegant Feathers: сохраните десять для второго послания Otho.",
	["The central hills"] = "Центральные холмы",
	["The crates of Hinterlands Honey Ripple lie around the abandoned Horde camp at Skulk Rock, among the oozes."] = "Ящики Hinterlands Honey Ripple лежат вокруг заброшенного лагеря Орды у Скалы Сокрытия, среди слизней.",
	["Skulk Rock"] = "Скала Сокрытия",
	["Only with the distress beacon: the robot sits at the head of the river west of Skulk Rock. Escort it east to the shore beyond the Overlook Cliffs; its reward waits with Oglethorpe in Booty Bay."] = "Только если есть аварийный маяк: робот сидит в верховьях реки к западу от Скалы Сокрытия. Сопроводите его на восток к берегу за Обзорными утёсами; награда ждёт у Oglethorpe в Пиратской Бухте.",
	["OOX-09/HL"] = "OOX-09/HL",
	["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "На юго-западе ревуны Silvermane бродят по холмам к востоку от деревень Witherbark.",
	["Silvermane Howlers"] = "Ревуны Silvermane",
	["Back west to Quel'Danil Lodge; rangers and marksmen stay near the lodge, scouts and outrunners on the slopes south of it."] = "Обратно на запад к Сторожке Кель'Данил; следопыты и стрелки держатся у сторожки, разведчики и бегуны — на склонах к югу.",
	["On the way back east, the Vilebranch soothsayers hold the Altar of Zul, the troll temple south of the central hills. Qiaga and Morta'gya the Keeper (elite, 50) stand at its top: take the soothsayers on the lower steps."] = "На обратном пути на восток предсказатели Vilebranch удерживают Алтарь Зула — храм троллей к югу от центральных холмов. Qiaga и Morta'gya the Keeper (элитная, 50) стоят наверху: бейте предсказателей на нижних ступенях.",
	["Vilebranch soothsayers"] = "Предсказатели Vilebranch",
	["His next request, going on to the Altar of Zul, is for a group."] = "Его следующая просьба — дальше к Алтарю Зула — для группы.",
	["Huntsman Malkhor's skull lies on a pile below the Vilebranch ruins, his bones on a pile at the foot of Jintha'Alor. The Vessels of Tainted Blood sit on the lower terraces, and Elder Torntusk is held at the top. Keep to the paths: the trolls inside are elite."] = "Череп Huntsman Malkhor лежит в куче под руинами Vilebranch, его кости — в куче у подножия Джинта'Алора. Сосуды с осквернённой кровью стоят на нижних террасах, а Elder Torntusk в плену наверху. Держитесь троп: тролли внутри элитные.",
	["Jintha'Alor"] = "Джинта'Алор",
	["Ride all the way west to the Wildhammer town of Aerie Peak and place the message by the well in its centre. The town is full of Alliance guards: get in, place it and get out."] = "Езжайте на самый запад в город Громового Молота — Орлиное Гнездо — и положите послание у колодца в центре. В городе полно стражи Альянса: зайдите, положите и уходите.",
	["Aerie Peak"] = "Орлиное Гнездо",
	["Hearth to Revantusk Village"] = "Камень возвращения — в Деревню Сломанного Клыка",
	["The next guide starts here, at Revantusk Village."] = "Следующий гид начинается здесь, в Деревне Сломанного Клыка.",
	["Vulture hills"] = "Холмы грифов",
	["Get the flight path at Revantusk Village"] = "Возьмите точку полёта в Деревне Сломанного Клыка",
	["Aerie Peak well"] = "Колодец Орлиного Гнезда",
	["Azshara, Feralas & Stranglethorn Vale"] = "Азшара, Фералас и Тернистая долина",
	["From Revantusk Village's flight master, fly to the Undercity."] = "У распорядителя полётов Деревни Сломанного Клыка летите в Подгород.",
	["Oran stands in the Magic Quarter."] = "Oran стоит в Квартале магов.",
	["Oran Snakewrithe"] = "Oran Snakewrithe",
	["Fly to Splintertree Post"] = "Летите на Заставу Расщепленного Дерева",
	["Take the zeppelin to Orgrimmar from the tower outside the Undercity, then fly to Splintertree Post."] = "Сядьте на дирижабль в Оргриммар с башни у Подгорода, затем летите на Заставу Расщепленного Дерева.",
	["Ride east along the road out of Splintertree. Loh'atu waits at the Shadowsong Shrine just off the road, a few steps west of the Alliance's Talrendis Point: come in from the west and keep clear of the Azshara Sentinels and Jarrodenus (elite)."] = "Езжайте на восток по дороге от Заставы Расщепленного Дерева. Loh'atu ждёт у святилища Песни Теней у самой дороги, в нескольких шагах к западу от Мыса Талрендис Альянса: подходите с запада и держитесь подальше от часовых Азшары и Jarrodenus (элитный).",
	["Ride into Azshara"] = "Въезд в Азшару",
	["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "Призраки высокорождённых бродят по руинам сразу к северу от святилища; сатиры Haldarr стоят лагерем чуть севернее.",
	["Highborne and Haldarr satyrs"] = "Высокорождённые и сатиры Haldarr",
	["Back to Loh'atu at the shrine; stay west of the Talrendis Point guards."] = "Обратно к Loh'atu у святилища; держитесь западнее стражи Мыса Талрендис.",
	["Loh'atu"] = "Loh'atu",
	["Follow the road north to Valormok, the Horde camp."] = "Идите по дороге на север к Валормоку, лагерю Орды.",
	["Valormok"] = "Валормок",
	["The Thunderhead Hippogryphs fly over the hills just south of Valormok."] = "Гиппогрифы Thunderhead летают над холмами сразу к югу от Валормока.",
	["Undamaged Hippogryph Feathers"] = "Неповреждённые перья гиппогрифа",
	["Sanath Lim-yo"] = "Sanath Lim-yo",
	["Ride north-east to the goblin's camp on the cliffs above the Bay of Storms."] = "Езжайте на северо-восток к лагерю гоблина на утёсах над Заливом Бурь.",
	["Kim'jael"] = "Kim'jael",
	["The blood elves' camp lies just south of Kim'jael. His four pieces of equipment lie in the crates around the camp."] = "Лагерь эльфов крови — сразу к югу от Kim'jael. Четыре предмета его снаряжения лежат в ящиках вокруг лагеря.",
	["Thalassian Base Camp"] = "Талассийский лагерь",
	["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry Kim'jael's rune."] = "Езжайте на юго-запад к руинам. Четыре скрижали лежат среди руин под охраной наг Spitelash; руна Kim'jael может быть у любой сирены или мирмидона.",
	["Ruins of Eldarath"] = "Руины Эльдарата",
	["Back north-east to Kim'jael."] = "Обратно на северо-восток к Kim'jael.",
	["Keep the deliveries for Magatha, Jes'rimon and Andron Gant: you pass Thunder Bluff, Orgrimmar and the Undercity later."] = "Сохраните посылки для Magatha, Jes'rimon и Andron Gant: позже вы будете проходить Громовой Утес, Оргриммар и Подгород.",
	["Ride west back to Valormok."] = "Езжайте обратно на запад в Валормок.",
	["Jediga"] = "Jediga",
	["Xylem's tower stands on the cliff just north of Valormok; the path winds up its north side."] = "Башня Xylem стоит на утёсе сразу к северу от Валормока; тропа вьётся по её северной стороне.",
	["Archmage Xylem"] = "Archmage Xylem",
	["Fly from Valormok to Orgrimmar, walk out of the main gate to the zeppelin towers and take the zeppelin to Grom'gol."] = "Летите из Валормока в Оргриммар, выйдите через главные ворота к башням дирижаблей и садитесь на дирижабль в Гром'гол.",
	["To Grom'gol"] = "В Гром'гол",
	["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "Идите по дороге на юг; василиски греются на камнях к востоку от неё посреди джунглей. Осколки выпадают часто.",
	["Ironjaw Basilisks"] = "Железночелюстные василиски",
	["Continue south to Booty Bay. Oglethorpe Obnoticus has his workshop on the upper ring of the bay."] = "Продолжайте на юг в Пиратскую Бухту. Мастерская Oglethorpe Obnoticus — на верхнем ярусе бухты.",
	["Keep Jes'rimon's payment and Ag'tor's Betrayed: they go back to Valormok on a later visit."] = "Сохраните плату Jes'rimon и Ag'tor's Betrayed: они вернутся в Валормок в следующий раз.",
	["Take the zeppelin back to Orgrimmar."] = "Сядьте на дирижабль обратно в Оргриммар.",
	["Un'Goro Soil is gathered in the next guide; Magatha's payment goes back to Jediga later."] = "Почва Ун'Горо собирается в следующем гиде; плата Magatha позже вернётся к Jediga.",
	["Fly to Thunder Bluff; it is on the way to Camp Mojache. No flight path there yet? Fly to Camp Taurajo and ride west through Mulgore. Hamuul and Magatha are on the Elder Rise; Druids and Paladins train here (Turak Runetotem, Alodan the Hopeful)."] = "Летите в Громовой Утес — он по пути в Лагерь Мохаче. Точки полёта там ещё нет? Летите в Лагерь Таурахо и езжайте на запад через Мулгор. Hamuul и Magatha — на Вершине Старейшин; друиды и паладины учатся здесь (Turak Runetotem, Alodan the Hopeful).",
	["Keep Sunken Temple for Marvon in Tanaris."] = "Сохраните задание «Затонувший храм» для Marvon в Танарисе.",
	["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "Гиппогрифы гнездятся на холмах к юго-западу от лагеря. Убейте одного, затем используйте Muisek Vessel на его теле.",
	["Frayfeather Hippogryphs"] = "Гиппогрифы Frayfeather",
	["Witch Doctor Uzer'i"] = "Witch Doctor Uzer'i",
	["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "Волшебные дракончики порхают в лесу сразу к западу от лагеря. Используйте сосуд на каждом убитом.",
	["Sprite Darters"] = "Феи-стрекозы",
	["The treants wander the forest roads between the camp and the middle of Feralas; there are only a few, so look along the paths."] = "Древни бродят по лесным дорогам между лагерем и центром Фераласа; их мало, так что смотрите вдоль троп.",
	["Wandering Forest Walkers"] = "Бродячие лесные ходоки",
	["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with Zorbin's Ultra-Shrinker first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "Сухопутные ходоки и утёсные великаны бродят по холмам к северу от пристани. Сначала уменьшите каждого с помощью Zorbin's Ultra-Shrinker: уменьшенные, они больше не элитные. С каждого уменьшенного великана выпадает осадок; используйте на его теле и Muisek Vessel.",
	["Zapped giants"] = "Уменьшенные великаны",
	["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "Морские элементали и морские брызги ходят по берегу вокруг пристани.",
	["Sea elementals"] = "Морские элементали",
	["Back to Camp Mojache"] = "Обратно в Лагерь Мохаче",
	["Tran'rek's tar and Pestlezugg's samples come from Un'Goro Crater."] = "Смолу для Tran'rek и образцы для Pestlezugg добудете в Кратере Ун'Горо.",
	["Keep The Stone Circle: Marvon's chest is opened on a later visit."] = "Сохраните «Каменный круг»: сундук Marvon откроется позже.",
	["Ride south along the road to the Broken Pillar; Marvon Rivetseeker camps beside it. From here the road west leads down into Un'Goro Crater, where the next guide starts."] = "Езжайте на юг по дороге к Сломанной колонне; Marvon Rivetseeker стоит лагерем рядом. Отсюда дорога на запад ведёт вниз в Кратер Ун'Горо — там начинается следующий гид.",
	["Broken Pillar"] = "Сломанная колонна",
	["Get the flight path at Valormok"] = "Возьмите точку полёта в Валормоке",
	["Un'Goro Crater, Eastern Plaguelands & Burning Steppes"] = "Кратер Ун'Горо, Восточные Чумные земли и Пылающие степи",
	["From the Broken Pillar ride west to the long ramp that winds down into Un'Goro Crater, then follow the crater's north wall to Marshal's Refuge, a camp in the cliff caves. Everyone here is neutral."] = "От Сломанной колонны езжайте на запад к длинному спуску в Кратер Ун'Горо, затем вдоль северной стены кратера к Убежищу Маршалла — лагерю в пещерах утёса. Здесь все нейтральны.",
	["Into Un'Goro Crater"] = "В Кратер Ун'Горо",
	["From here on pick up every Power Crystal (blue, green, red, yellow) and every Un'Goro Soil pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "С этого момента подбирайте все кристаллы силы (синие, зелёные, красные, жёлтые) и все кучки почвы Ун'Горо по пути: всего 25 почвы — 20 для Hamuul и 5 для Pestlezugg.",
	["Out of the refuge"] = "Из убежища",
	["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the Super Sticky Tar."] = "Смоляные ямы — сразу к югу от убежища. Со смоляных зверей, таящихся и ползучих выпадает суперлипкая смола.",
	["Lakkari Tar Pits"] = "Смоляные ямы Лаккари",
	["Ride south-west along the western cliffs. Frenzied Pterrordax fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "Езжайте на юго-запад вдоль западных утёсов. Бешеные птеррордаксы летают над западной частью, ловушки-кровоцветы растут в тех же джунглях.",
	["Western jungle"] = "Западные джунгли",
	["A Mangled Journal, a rare drop"] = "A Mangled Journal, редкая добыча",
	["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales Shizzle wants. Ravasaurs hunt in packs in the south-west: their claws are for Jes'rimon, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "К югу от горячих источников пасутся стегодоны; кости динозавров выпадают с них или лежат на земле; диметродоны рядом несут чешую для Shizzle. Равазавры охотятся стаями на юго-западе: их когти — для Jes'rimon, и иногда у одного находится Mangled Journal (редкая добыча: берите его задание, только если выпал). Обходите Gruff — стегодона 57 уровня.",
	["Stegodons and ravasaurs"] = "Стегодоны и равазавры",
	["The expedition's lost equipment lies in the south-west jungle."] = "Потерянное снаряжение экспедиции лежит в юго-западных джунглях.",
	["Research Equipment"] = "Исследовательское снаряжение",
	["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. Pterrordax nest on the cliffs above the hive; their scales are for Shizzle."] = "Улей силитидов занимает юг кратера. С ос и рабочих Gorishi выпадает пахучая железа; используйте Scraping Vial на кладке яиц в первом зале. Королева улья внизу — элитный босс: не заходите в её зал. Птеррордаксы гнездятся на утёсах над ульем; их чешуя — для Shizzle.",
	["The Gorishi hive"] = "Улей Gorishi",
	["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "Плот лежит на берегу юго-восточного озера; небольшой мешок — в воде рядом.",
	["A Wrecked Raft"] = "Разбитый плот",
	["Torwa camps in the south-east corner of the crater."] = "Torwa стоит лагерем в юго-восточном углу кратера.",
	["Torwa Pathfinder"] = "Torwa Pathfinder",
	["North of Torwa, a dead Threshadon lies by the water."] = "К северу от Torwa у воды лежит мёртвый трешадон.",
	["Fresh Threshadon Carcass"] = "Свежая туша трешадона",
	["The Lar'korwi Mates prowl the jungle north-west of Torwa."] = "Самки Lar'korwi рыщут по джунглям к северо-западу от Torwa.",
	["Lar'korwi Mates"] = "Самки Lar'korwi",
	["Keep the bait: Lar'korwi is level 56, and the second loop passes his lair."] = "Сохраните приманку: Lar'korwi 56 уровня, а второй круг проходит мимо его логова.",
	["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "Езжайте на север по восточной стороне. Кровоцветы-хлестуны и молотильщики заполняют джунгли.",
	["Lashers and Threshers"] = "Хлестуны и молотильщики",
	["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "Ящик экспедиции стоит в заброшенном лагере в восточных джунглях.",
	["Crate of Foodstuffs"] = "Ящик с припасами",
	["A-Me 01 then wants a Mithril Casing, an Engineering item. Skip it unless you have one."] = "Дальше A-Me 01 просит Mithril Casing — предмет инженерного дела. Пропустите, если у вас его нет.",
	["The gorillas live on the north-east plateau. Stay out of the deepest cave: U'cha lives there."] = "Гориллы живут на северо-восточном плато. Не заходите в самую глубокую пещеру: там живёт U'cha.",
	["Gorillas"] = "Гориллы",
	["Ride south-west to Fire Plume Ridge, the volcano in the middle of the crater. Bloodpetal Flayers grow around its foot."] = "Езжайте на юго-запад к Огненному гребню — вулкану в центре кратера. У его подножия растут кровоцветы-живодёры.",
	["Bloodpetal Flayers"] = "Кровоцветы-живодёры",
	["The crystal clusters stand all over the crater, many around Fire Plume Ridge. Take a few extra of each colour for the pylons."] = "Скопления кристаллов есть по всему кратеру, много — вокруг Огненного гребня. Возьмите по несколько лишних каждого цвета для пилонов.",
	["Power Crystals and soil"] = "Кристаллы силы и почва",
	["Ringo sits on the ridge, lost and exhausted."] = "Ringo сидит на гребне, заблудившийся и измождённый.",
	["Ringo"] = "Ringo",
	["Lead Ringo north to Marshal's Refuge. When he faints, use Spraggle's Canteen on him to wake him."] = "Ведите Ringo на север к Убежищу Маршалла. Когда он падает в обморок, используйте на нём Spraggle's Canteen, чтобы привести в чувство.",
	["Escort Ringo"] = "Сопровождение Ringo",
	["Keep Larion's Marvon's Workshop and Linken's letter for later guides."] = "Сохраните «Мастерскую Marvon» от Larion и письмо Linken для следующих гидов.",
	["Marshal's Refuge"] = "Убежище Маршалла",
	["The pylon stands on the slope east of the refuge."] = "Пилон стоит на склоне к востоку от убежища.",
	["Northern Pylon"] = "Северный пилон",
	["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "Спуститесь по восточной стороне кратера к пилону на восточных утёсах.",
	["Eastern Pylon"] = "Восточный пилон",
	["Lar'korwi's lair is just south of the pylon. Use Torwa's bait there; Lar'korwi is level 56 and hits hard, so start at full health."] = "Логово Lar'korwi — сразу к югу от пилона. Используйте там приманку Torwa; Lar'korwi 56 уровня и бьёт сильно, начинайте с полным здоровьем.",
	["Lar'korwi"] = "Lar'korwi",
	["Torwa now asks for U'cha's pelt, back in the north-east cave: skip it."] = "Теперь Torwa просит шкуру U'cha из северо-восточной пещеры: пропустите.",
	["Cross the south of the crater to the pylon on the western cliffs."] = "Пересеките юг кратера к пилону на западных утёсах.",
	["Western Pylon"] = "Западный пилон",
	["Krakle the goblin sits at Golakka Hot Springs, just east of the pylon."] = "Гоблин Krakle сидит у горячих источников Голакка, сразу к востоку от пилона.",
	["Krakle"] = "Krakle",
	["Ride east to Fire Plume Ridge, climb it and use Krakle's Thermometer at the lava vent near the top, then ride back west to Krakle."] = "Езжайте на восток к Огненному гребню, поднимитесь и используйте Krakle's Thermometer у лавового жерла почти на вершине, затем вернитесь на запад к Krakle.",
	["Krakle's Thermometer"] = "Термометр Krakle",
	["Krakle sends you to Donova Snowden in Winterspring: keep it."] = "Krakle отправит вас к Donova Snowden в Зимние Ключи: сохраните задание.",
	["Ride north back to Marshal's Refuge."] = "Езжайте обратно на север к Убежищу Маршалла.",
	["J.D. Collie"] = "J.D. Collie",
	["Theodora's quest in Kargath needs level 52. The Tar Lurkers and Tar Lords just south of the refuge are the closest camp."] = "Задание Theodora в Каргате требует 52 уровня. Ближайший лагерь — смоляные таящиеся и смоляные лорды сразу к югу от убежища.",
	["Pestlezugg's next quest needs the Gorishi Hive Queen, an elite boss. Skip it."] = "Следующее задание Pestlezugg требует убить королеву улья Gorishi — элитного босса. Пропустите.",
	["Fly to Orgrimmar and train before the Grom'gol zeppelin: the Undercity stop later in this guide has no Hunter or Shaman trainer."] = "Летите в Оргриммар и потренируйтесь до дирижабля в Гром'гол: в Подгороде позже по этому гиду нет учителей охотников и шаманов.",
	["Fly to Thunder Bluff and train with Turak Runetotem on Elder Rise, then fly to Orgrimmar for the Grom'gol zeppelin."] = "Летите в Громовой Утес и потренируйтесь у Turak Runetotem на Вершине Старейшин, затем летите в Оргриммар к дирижаблю в Гром'гол.",
	["Fly to Orgrimmar, take the zeppelin to Grom'gol and fly from there to Kargath, built into the cliffs on the Badlands' west edge."] = "Летите в Оргриммар, садитесь на дирижабль в Гром'гол и оттуда летите в Каргат — крепость в скалах на западном краю Бесплодных земель.",
	["Take the pass out of Kargath's west side into the Searing Gorge, then ride south across the gorge to the long bridge into Blackrock Mountain. Inside, follow the chain walkways down and leave through the southern exit; stay off the paths to the dungeon portals."] = "Пройдите через перевал с западной стороны Каргата в Тлеющее ущелье, затем езжайте на юг через ущелье к длинному мосту в Черную гору. Внутри спускайтесь по цепным мосткам и выходите через южный выход; не сворачивайте к порталам подземелий.",
	["Into the Searing Gorge"] = "В Тлеющее ущелье",
	["The mountain lets you out beside Blackrock Stronghold, full of 55-57 orcs. Follow the road east along the northern cliffs to the Horde camp at Flame Crest."] = "Гора выпускает вас рядом с Крепостью Черной горы, полной орков 55-57 уровня. Идите по дороге на восток вдоль северных утёсов к лагерю Орды на Огненном Гребне.",
	["Flame Crest"] = "Огненный Гребень",
	["Black Broodlings nest in the hills just east of Flame Crest. Use Tinkee's Draco-Incarcinatrix 900 on a broodling when it is almost dead to capture its essence."] = "Черные выводки гнездятся на холмах сразу к востоку от Огненного Гребня. Используйте Tinkee's Draco-Incarcinatrix 900 на почти мёртвом детёныше, чтобы поймать его сущность.",
	["Black Broodlings"] = "Черные детёныши",
	["Follow the cliffs south to Dreadmaul Rock, the Firegut ogres' hill. Sha'ni Proudtusk's remains lie at its foot."] = "Идите вдоль утёсов на юг к Скале Жуткой Палицы — холму огров Firegut. Останки Sha'ni Proudtusk лежат у подножия.",
	["Sha'ni Proudtusk"] = "Sha'ni Proudtusk",
	["Krom'Grul walks the caves and mine tunnels of Dreadmaul Rock; if he isn't home, clear the ogres around the entrances until he comes back."] = "Krom'Grul ходит по пещерам и шахтным туннелям Скалы Жуткой Палицы; если его нет, перебейте огров у входов, пока он не вернётся.",
	["Krom'Grul"] = "Krom'Grul",
	["Ride west to the dig site. War Reaver golems (53) stomp around it and drop the shards often; the Tablet of the Seven stands in its middle among the Thaurissan dwarves. Copy it."] = "Езжайте на запад к раскопкам. Големы War Reaver (53) топчутся вокруг и часто роняют осколки; Скрижаль Семи стоит в центре среди дворфов Тауриссана. Скопируйте её.",
	["Thaurissan dig site"] = "Раскопки Тауриссана",
	["Keep Tinkee's letter: Felnok Steelspring is in Everlook, Winterspring."] = "Сохраните письмо Tinkee: Felnok Steelspring — в Круговзоре, Зимние Ключи.",
	["Back north-east to Flame Crest."] = "Обратно на северо-восток к Огненному Гребню.",
	["Theodora's next errand goes to Lotwil east of town and then into Blackrock Depths: skip it."] = "Следующее поручение Theodora ведёт к Lotwil к востоку от города, а потом в Глубины Черной горы: пропустите.",
	["Take a Box of Incendiaries from the crate next to Derrington for Scarlet Diversions, done on the way back. Equip the Argent Dawn Commission: Scourgestones only drop while you wear it."] = "Возьмите Box of Incendiaries из ящика рядом с Derrington для задания «Отвлекающий манёвр Алого ордена» — оно делается на обратном пути. Наденьте Argent Dawn Commission: камни Плети выпадают, только пока он надет.",
	["Leave the Undercity and ride east along the road through Tirisfal Glades to the Bulwark, the Forsaken fort on the border."] = "Выйдите из Подгорода и езжайте на восток по дороге через Тирисфальские леса к Бастиону — форту Отрекшихся на границе.",
	["The Bulwark"] = "Бастион",
	["Follow the road east through the Western Plaguelands and across the river into the Eastern Plaguelands; leave it north for Terrordale, the ruined town in the north-west. Augustus sits in a hut at its edge."] = "Идите по дороге на восток через Западные Чумные земли и через реку в Восточные Чумные земли; сверните на север к Долине Ужаса — разрушенному городу на северо-западе. Augustus сидит в хижине на окраине.",
	["Augustus the Touched"] = "Augustus the Touched",
	["The book lies in the ruined inn of Terrordale."] = "Книга лежит в разрушенной таверне Долины Ужаса.",
	["Augustus' Receipt Book"] = "Книга расписок Augustus",
	["The Large Termite Mounds stand all over the hills east of Terrordale. Use the Empty Termite Jar on each mound you pass."] = "Большие термитники стоят по всем холмам к востоку от Долины Ужаса. Используйте Empty Termite Jar на каждом термитнике по пути.",
	["Termite mounds"] = "Термитники",
	["Ride south back to the road and follow it east across the whole zone to Light's Hope Chapel."] = "Езжайте на юг обратно к дороге и по ней на восток через всю зону к Часовне Последней Надежды.",
	["Light's Hope Chapel"] = "Часовня Последней Надежды",
	["With Carlin's quest in your log, slain Scourge sometimes leave a Darrowshire Spirit; talk to it to free it. Kill undead on the ride south-west to Darrowshire."] = "Пока задание Carlin в журнале, из убитой Плети иногда выходит дух Дарроушира; поговорите с ним, чтобы освободить. Убивайте нежить по пути на юго-запад к Дарроуширу.",
	["Darrowshire Spirits"] = "Духи Дарроушира",
	["Pamela's ghost stands in the ruins of Darrowshire, in the south-west."] = "Призрак Pamela стоит в руинах Дарроушира, на юго-западе.",
	["Pamela Redpath"] = "Pamela Redpath",
	["The doll's head and its two sides lie in the houses around Pamela; join them from your bags."] = "Голова куклы и две её половинки лежат в домах вокруг Pamela; соедините их в сумке.",
	["Pamela's Doll"] = "Кукла Pamela",
	["Keep Auntie Marlene: Marlene lives at Sorrow Hill in the Western Plaguelands."] = "Сохраните «Тётушку Марлен»: Marlene живёт на Холме Печали в Западных Чумных землях.",
	["Zaeldarr lurks just west of Darrowshire."] = "Zaeldarr прячется сразу к западу от Дарроушира.",
	["Zaeldarr the Outcast"] = "Zaeldarr the Outcast",
	["Hearth to Light's Hope Chapel"] = "Камень возвращения — в Часовню Последней Надежды",
	["The next guide starts here, at the chapel's flight master."] = "Следующий гид начинается здесь, у распорядителя полётов часовни.",
	["Back to Light's Hope Chapel"] = "Обратно в Часовню Последней Надежды",
	["Get the flight path at Marshal's Refuge"] = "Возьмите точку полёта в Убежище Маршалла",
	["Northern Crystal Pylon"] = "Северный кристаллический пилон",
	["Eastern Crystal Pylon"] = "Восточный кристаллический пилон",
	["Western Crystal Pylon"] = "Западный кристаллический пилон",
	["Bridge into Blackrock Mountain"] = "Мост в Черную гору",
	["Get the flight path at Flame Crest"] = "Возьмите точку полёта на Огненном Гребне",
	["Get the flight path at Light's Hope Chapel"] = "Возьмите точку полёта в Часовне Последней Надежды",
	["Felwood & Western Plaguelands"] = "Оскверненный лес и Западные Чумные земли",
	["From Light's Hope Chapel's flight master, fly to the Undercity."] = "У распорядителя полётов Часовни Последней Надежды летите в Подгород.",
	["Keep the parcel: Royal Overseer Bauhaus is in the Undercity."] = "Сохраните посылку: Royal Overseer Bauhaus — в Подгороде.",
	["Leave the Undercity and ride east along the road through Tirisfal Glades, past the Bulwark. Felstone Farm is the first farm along the road; Janice waits in the house."] = "Выйдите из Подгорода и езжайте на восток по дороге через Тирисфальские леса, мимо Бастиона. Ферма Камня Скверны — первая ферма у дороги; Janice ждёт в доме.",
	["Janice Felstone"] = "Janice Felstone",
	["Scarlet Crusade Forward Camp"] = "Передовой лагерь Алого ордена",
	["The Scarlet Crusade's tents stand between Felstone Field and Dalson's Tears. Torch the command tent with the Box of Incendiaries and plant the Scourge banner."] = "Палатки Алого ордена стоят между Полем Камня Скверны и Слезами Далсона. Подожгите командирскую палатку с помощью Box of Incendiaries и установите знамя Плети.",
	["Scarlet forward camp"] = "Передовой лагерь Алого ордена",
	["The diary lies in the farmhouse, the cabinet stands inside and the outhouse is behind it. A Wandering Skeleton carries the outhouse key; Farmer Dalson comes out when you open the outhouse and carries the cabinet key."] = "Дневник лежит в доме фермы, шкаф стоит внутри, сортир — за домом. Ключ от сортира у бродячего скелета; Farmer Dalson выходит, когда вы открываете сортир, и у него ключ от шкафа.",
	["Dalson's Tears farmhouse"] = "Дом фермы Слезы Далсона",
	["He camps by the Writhing Haunt, south-east of Dalson's Tears."] = "Он стоит лагерем у Гнезда Корчащихся, к юго-востоку от Слез Далсона.",
	["Mulgris Deepriver"] = "Mulgris Deepriver",
	["Keep Little Pamela: Pamela is in Darrowshire, visited again later."] = "Сохраните «Малышку Памелу»: Pamela — в Дарроушире, куда вы ещё вернётесь.",
	["Ride south past the Writhing Haunt to Sorrow Hill; Marlene's house stands by the road, and Joseph Redpath's monument is in the graveyard behind it. Kill the Diseased Wolves you meet in the fields on the way."] = "Езжайте на юг мимо Гнезда Корчащихся к Холму Печали; дом Marlene стоит у дороги, памятник Joseph Redpath — на кладбище за ним. По пути убивайте больных волков на полях.",
	["Sorrow Hill"] = "Холм Печали",
	["Ride north-west into Andorhal. Chromie waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "Езжайте на северо-запад в Андорал. Chromie ждёт в разрушенной таверне на западной стороне города; скелеты внутри — 54-57 уровня, держитесь окраин.",
	["Chromie"] = "Chromie",
	["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "Летопись лежит среди затхлых томов в ратуше Андорала; открывайте их, пока не найдёте нужный.",
	["The Annals of Darrowshire"] = "Летопись Дарроушира",
	["Brother Carlin goes to Light's Hope Chapel: keep it for later."] = "Brother Carlin — в Часовне Последней Надежды: сохраните на потом.",
	["The wolves roam the fields between Andorhal, Dalson's Tears and the Writhing Haunt. Finish them on the ride back east."] = "Волки бродят по полям между Андоралом, Слезами Далсона и Гнездом Корчащихся. Добейте их по пути обратно на восток.",
	["Diseased Wolves"] = "Больные волки",
	["The bears roam the hills north and east of the Writhing Haunt."] = "Медведи бродят по холмам к северу и востоку от Гнезда Корчащихся.",
	["Diseased Grizzlies"] = "Больные гризли",
	["Keep the branch: Nara Wildmane is in Thunder Bluff."] = "Сохраните ветвь: Nara Wildmane — в Громовом Утесе.",
	["Tirion's hunts are in the Eastern Plaguelands: keep them for later."] = "Охоты для Tirion — в Восточных Чумных землях: сохраните на потом.",
	["Ride north along the eastern hills; Tirion lives in a small house by the Thondroril River, at the border with the Eastern Plaguelands."] = "Езжайте на север вдоль восточных холмов; Tirion живёт в маленьком доме у реки Тондрорил, на границе с Восточными Чумными землями.",
	["Tirion Fordring"] = "Tirion Fordring",
	["Ride west to the Northridge Lumber Camp; Kirsta hides on the hill north-east of it."] = "Езжайте на запад к Лесопилке Северного Кряжа; Kirsta прячется на холме к северо-востоку от неё.",
	["Kirsta Deepshadow"] = "Kirsta Deepshadow",
	["Knights and magi work the Northridge Lumber Camp; the medics and hunters camp south of it."] = "Рыцари и маги работают на Лесопилке Северного Кряжа; лекари и охотники стоят лагерем к югу от неё.",
	["Scarlet Crusade"] = "Алый орден",
	["Huntsman Radley stands east of the lumber camp; Cavalier Durgen guards the road north-east of Kirsta, toward Hearthglen."] = "Huntsman Radley стоит к востоку от лесопилки; Cavalier Durgen охраняет дорогу к северо-востоку от Kirsta, в сторону Дольного Очага.",
	["Radley and Durgen"] = "Radley и Durgen",
	["Kirsta's last task needs level 53. The Scarlet Knights and Magi (54-55) working the lumber camp just south-west of her are the closest camp."] = "Последнее задание Kirsta требует 53 уровня. Ближайший лагерь — алые рыцари и маги (54-55) на лесопилке сразу к юго-западу от неё.",
	["Northridge Lumber Camp"] = "Лесопилка Северного Кряжа",
	["Hearthglen's Scarlets are level 58-60. Ride in to the high point marked on your map, look over the town, and get out."] = "Алые в Дольном Очаге — 58-60 уровня. Доберитесь до высокой точки, отмеченной на карте, осмотрите город и уходите.",
	["Hearthglen"] = "Дольный Очаг",
	["Derrington's watchtowers, Vandis' cauldron and Mickey's barrel are done on a later visit: keep them."] = "Сторожевые башни Derrington, котёл Vandis и бочка Mickey — в следующий раз: сохраните задания.",
	["Ride south-west past Felstone Farm and follow the road west back to the Bulwark."] = "Езжайте на юго-запад мимо Фермы Камня Скверны и по дороге на запад обратно к Бастиону.",
	["Ride back to the Undercity, take the zeppelin to Orgrimmar and fly to Splintertree Post. Follow the road west out of Splintertree and take the fork north into Felwood."] = "Вернитесь в Подгород, садитесь на дирижабль в Оргриммар и летите на Заставу Расщепленного Дерева. Идите по дороге на запад от заставы и на развилке сверните на север в Оскверненный лес.",
	["To Felwood"] = "В Оскверненный лес",
	["The druids' camp is just past the border."] = "Лагерь друидов — сразу за границей.",
	["Emerald Sanctuary"] = "Изумрудное святилище",
	["Follow the road north-west. The south of Jaedenar, around its corrupted moonwell, is held by Shadow Council cultists, adepts, guardsmen and their hounds."] = "Идите по дороге на северо-запад. Юг Джеденара вокруг осквернённого лунного колодца держат культисты, адепты, стражники Совета Теней и их гончие.",
	["Southern Jaedenar"] = "Южный Джеденар",
	["Only if a Blood Red Key dropped: use it to start the quest, then free Arko'narin in her cage in Shadow Hold, the cave at the north end of Jaedenar, and escort her out."] = "Только если выпал Blood Red Key: используйте его, чтобы начать задание, затем освободите Arko'narin из клетки в Темной Твердыне — пещере в северном конце Джеденара — и выведите её.",
	["A Strange Red Key"] = "Странный красный ключ",
	["Ride back south-east to the Sanctuary."] = "Езжайте обратно на юго-восток к святилищу.",
	["The Deadwood furbolg village lies just south of the Sanctuary. Every Deadwood kill also raises your Timbermaw Hold reputation; keep the headdress feathers."] = "Деревня фурболгов Мертвого Леса — сразу к югу от святилища. Каждое убийство Мертвого Леса повышает репутацию с Древобрюхими; сохраняйте перья с головных уборов.",
	["Deadwood Village"] = "Деревня Мертвого Леса",
	["Grazle"] = "Grazle",
	["Back north to Jaedenar. Fill Greta's canteen at the corrupted moonwell in the middle of the southern camp."] = "Обратно на север к Джеденару. Наполните флягу Greta у осквернённого лунного колодца посреди южного лагеря.",
	["The Jaedenar moonwell"] = "Лунный колодец Джеденара",
	["Only if you rescued Arko'narin: the succubus Rakaiah waits in the middle of Jaedenar, beside the Remains of Trey Lightforge."] = "Только если вы спасли Arko'narin: суккуб Rakaiah ждёт посреди Джеденара, у останков Trey Lightforge.",
	["Rakaiah"] = "Rakaiah",
	["The Horde camp just north of Jaedenar."] = "Лагерь Орды сразу к северу от Джеденара.",
	["Bloodvenom Post"] = "Застава Кровавой Топи",
	["Ride back south past Jaedenar to the corrupted moonwell of the Jadefire satyrs and fill Winna's flasket there."] = "Езжайте обратно на юг мимо Джеденара к осквернённому лунному колодцу сатиров Нефритового Пламени и наполните там флягу Winna.",
	["The Jadefire moonwell"] = "Лунный колодец Нефритового Пламени",
	["Winna Hazzard"] = "Winna Hazzard",
	["Take the kitten to the same moonwell and release it there; once it has turned into a Corrupted Saber, bring it back to Winna and click on it to hand it over."] = "Отнесите котёнка к тому же лунному колодцу и выпустите его там; когда он превратится в осквернённого саблезуба, приведите его обратно к Winna и нажмите на него, чтобы отдать.",
	["Winna's kitten"] = "Котёнок Winna",
	["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "К востоку от Заставы Кровавой Топи — изрытая кратерами долина, где бродят энтропические звери и ужасы. Убейте по два каждого, затем подойдите к каждому из трёх кратеров с водой Скверны.",
	["Shatter Scar Vale"] = "Долина Шрама",
	["Follow the road north-east to Irontree Woods. The Warpwood Moss Flayers and Shredders on the east side of the woods each carry a Blood Amber; Angerclaw Grizzlies and Felpaw Ravagers roam the same woods for Talo."] = "Идите по дороге на северо-восток к Железнолесью. У мшистых живодёров и кромсателей Warpwood на востоке леса есть кровавый янтарь; гризли Angerclaw и опустошители Felpaw бродят там же — это для Talo.",
	["Irontree Woods"] = "Железнолесье",
	["The road ends at Nafien, outside the Timbermaw Hold tunnel in the far north-east."] = "Дорога заканчивается у Nafien, перед туннелем Крепости Древобрюхов на дальнем северо-востоке.",
	["Nafien"] = "Nafien",
	["Deadwood Ritual Totem, a rare drop"] = "Deadwood Ritual Totem, редкая добыча",
	["The Deadwood furbolg village just west of the tunnel. Chieftain Bloodmaw (56) stands among them. Meilosh, a friendly furbolg, sits at the north end of the village."] = "Деревня фурболгов Мертвого Леса сразу к западу от туннеля. Chieftain Bloodmaw (56) стоит среди них. Meilosh, дружелюбный фурболг, сидит в северном конце деревни.",
	["Felpaw Village"] = "Деревня Felpaw",
	["Keep Speak to Salfa for Winterspring."] = "Сохраните «Поговорите с Salfa» для Зимних Ключей.",
	["Keep Seeking Spiritual Aid: Islen Waterseer is in the Barrens."] = "Сохраните «В поисках духовной помощи»: Islen Waterseer — в Степях.",
	["Ride the road south through Felwood to the Sanctuary."] = "Езжайте по дороге на юг через Оскверненный лес к святилищу.",
	["Ror stands at the far south end of Deadwood Village."] = "Ror стоит в дальнем южном конце Деревни Мертвого Леса.",
	["Overlord Ror"] = "Overlord Ror",
	["Ride north up the road again."] = "Снова на север по дороге.",
	["Back at Felpaw Village, the Deadwood furbolgs (53-54) are close to the tunnel and every kill raises your Timbermaw reputation."] = "Вернувшись в Деревню Felpaw: фурболги Мертвого Леса (53-54) стоят близко к туннелю, и каждое убийство повышает репутацию с Древобрюхими.",
	["Walk into the Timbermaw Hold tunnel beside Nafien and never attack the Timbermaw furbolgs inside. The tunnel opens into Winterspring; follow the road east to Everlook, the goblin town where the next guide starts."] = "Зайдите в туннель Крепости Древобрюхов рядом с Nafien и ни в коем случае не нападайте на фурболгов Древобрюхих внутри. Туннель выходит в Зимние Ключи; идите по дороге на восток в Круговзор — гоблинский город, где начинается следующий гид.",
	["Through Timbermaw Hold"] = "Через Крепость Древобрюхов",
	["Get the flight path at Bloodvenom Post"] = "Возьмите точку полёта на Заставе Кровавой Топи",
	["Jadefire moonwell"] = "Лунный колодец Нефритового Пламени",
	["Southern crater"] = "Южный кратер",
	["Western crater"] = "Западный кратер",
	["Northern crater"] = "Северный кратер",
	["Get the flight path at Everlook"] = "Возьмите точку полёта в Круговзоре",
	["Winterspring & Feralas"] = "Зимние Ключи и Фералас",
	["Gregor's and Harlo's quests lead to other zones: keep them."] = "Задания Gregor и Harlo ведут в другие зоны: сохраните их.",
	["Everlook is the goblin town on the east side of the valley."] = "Круговзор — гоблинский город на восточной стороне долины.",
	["Everlook"] = "Круговзор",
	["The yeti hills start just south-east of Everlook. Every yeti drops fur; only Matriarchs and Patriarchs drop horns, so keep those for after the turn-in."] = "Холмы йети начинаются сразу к юго-востоку от Круговзора. Мех выпадает со всех йети; рога — только с матриархов и патриархов, так что берегите их на после сдачи.",
	["Ice Thistle yetis"] = "Йети Ледяного Чертополоха",
	["Umi Rumplesnicker"] = "Umi Rumplesnicker",
	["Matriarchs and Patriarchs hit hard: pull them one at a time."] = "Матриархи и патриархи бьют сильно: тяните по одному.",
	["Pristine Yeti Horns"] = "Безупречные рога йети",
	["Umi's third prank targets goblins in Gadgetzan and Un'Goro: keep it for later."] = "Третья шалость Umi направлена на гоблинов в Прибамбасске и Ун'Горо: сохраните на потом.",
	["The chimaeras roam the snowfields south and west of Everlook. Stay clear of Mazthoril's cave: its blue dragonkin are elite."] = "Химеры бродят по снежным полям к югу и западу от Круговзора. Держитесь подальше от пещеры Мазторила: там элитные синие драконы.",
	["Chillwind chimaeras"] = "Химеры Chillwind",
	["Felnok Steelspring"] = "Felnok Steelspring",
	["Ride west along the road past Lake Kel'Theril; Raging Owlbeasts roam the hills north of it."] = "Езжайте на запад по дороге мимо озера Кель'Терил; бешеные совухи бродят по холмам к северу от него.",
	["Raging Owlbeasts"] = "Бешеные совухи",
	["The Videre Elixir comes from Gregan Brewspewer in Feralas, later in this guide."] = "Эликсир Видере даст Gregan Brewspewer в Фераласе, позже по этому гиду.",
	["Donova camps among the steaming pools of Frostfire Hot Springs, in the west of the valley."] = "Donova стоит лагерем среди дымящихся прудов горячих источников Морозного Огня на западе долины.",
	["Donova Snowden"] = "Donova Snowden",
	["Salfa stands by the Winterspring exit of Timbermaw Hold's tunnel, north of the hot springs."] = "Salfa стоит у выхода из туннеля Крепости Древобрюхов в Зимних Ключах, к северу от горячих источников.",
	["Salfa"] = "Salfa",
	["Empty Firewater Flask, a rare drop from the Winterfall furbolgs"] = "Empty Firewater Flask, редкая добыча с фурболгов Зимней Спячки",
	["Winterfall Ritual Totem, a rare drop from the Winterfall furbolgs"] = "Winterfall Ritual Totem, редкая добыча с фурболгов Зимней Спячки",
	["Pathfinders, Den Watchers and Totemics share the furbolg camps around the hot springs; Ragged Owlbeasts roam the slopes between them. Kill Totemics first. Save every Runecloth you loot for Meilosh."] = "Следопыты, стражи логова и тотемщики делят лагеря фурболгов вокруг горячих источников; облезлые совухи бродят по склонам между ними. Сначала убивайте тотемщиков. Сохраняйте всю руническую ткань для Meilosh.",
	["Frostfire Winterfall camps"] = "Лагеря Зимней Спячки у Морозного Огня",
	["Falling to Corruption is turned in at the Deadwood Cauldron in Felwood, on a later trip."] = "«Падение во тьму» сдаётся у Котла Мертвого Леса в Оскверненном лесу, в следующий раз.",
	["Ride east, then south down Frostwhisper Gorge. The Frostmaul giants there are elite level 59: keep to the middle and keep moving. The strange source is at the mouth of Darkwhisper Gorge, at the south end."] = "Езжайте на восток, затем на юг через Ущелье Ледяного Шёпота. Великаны Frostmaul там — элитные 59 уровня: держитесь середины и не останавливайтесь. Странный источник — у входа в Ущелье Темного Шёпота, в южном конце.",
	["Darkwhisper Gorge"] = "Ущелье Темного Шёпота",
	["The furbolg village fills the valley north-east of Everlook. Kill Shamans first; they heal. High Chief Winterfall in the cave at the back is elite: stay out."] = "Деревня фурболгов занимает долину к северо-востоку от Круговзора. Сначала убивайте шаманов: они лечат. High Chief Winterfall в пещере в глубине — элитный: не заходите.",
	["Winterfall Village"] = "Деревня Зимней Спячки",
	["Ride back west to Frostfire Hot Springs."] = "Езжайте обратно на запад к горячим источникам Морозного Огня.",
	["Any Winterfall furbolg can carry the beads; the camps just south of Salfa are the closest."] = "Бусы могут быть у любого фурболга Зимней Спячки; ближайшие лагеря — сразу к югу от Salfa.",
	["Beads for Salfa"] = "Бусы для Salfa",
	["Hearth to Everlook"] = "Камень возвращения — в Круговзор",
	["Back to Everlook"] = "Обратно в Круговзор",
	["Grind to 55"] = "Докачайтесь до 55",
	["A Little Luck"] = "Немного удачи",
	["Gregan Brewspewer, a dwarf, camps in the Lower Wilds north-west of Camp Mojache; he has the elixir."] = "Дворф Gregan Brewspewer стоит лагерем в Нижних Дебрях к северо-западу от Лагеря Мохаче; эликсир у него.",
	["The Videre Elixir"] = "Эликсир Видере",
	["Back at Camp Mojache."] = "Снова в Лагере Мохаче.",
	["Talo Thornhoof"] = "Talo Thornhoof",
	["He stands on Hunter Rise. Each donation wants cloth from your bags; hand them in when you have it, later in the route."] = "Он стоит на Вершине Охотников. Каждое пожертвование требует ткани из сумок; сдавайте, когда будет, позже по маршруту.",
	["Rumstag Proudstrider"] = "Rumstag Proudstrider",
	["Bluff Runner Windstrider"] = "Bluff Runner Windstrider",
	["Rabine Saturna waits in Moonglade: keep it for later."] = "Rabine Saturna ждёт на Лунной поляне: сохраните на потом.",
	["Elder Rise"] = "Вершина Старейшин",
	["Bashana buys Morrowgrain grown from your Un'Goro Soil."] = "Bashana покупает утреннее зерно, выращенное из почвы Ун'Горо.",
	["Bashana Runetotem"] = "Bashana Runetotem",
	["In the Valley of Spirits."] = "В Аллее Духов.",
	["Vehena"] = "Vehena",
	["In the Valley of Honor."] = "В Аллее Чести.",
	["Rashona Straglash"] = "Rashona Straglash",
	["Frostfire Winterfall camp"] = "Лагерь Зимней Спячки у Морозного Огня",
	["Gregan Brewspewer"] = "Gregan Brewspewer",
	["Azshara, The Barrens & Undercity"] = "Азшара, Степи и Подгород",
	["Fly to the Crossroads"] = "Летите в Перекрёсток",
	["Dokimi stands in the Crossroads. Open each crate she hands you and bring back what is inside."] = "Dokimi стоит в Перекрёстке. Открывайте каждый ящик, что она даёт, и приносите обратно содержимое.",
	["Dokimi's crates"] = "Ящики Dokimi",
	["Liv's workshop is at the north end of Ratchet's docks; Marvon's Chest stands inside it."] = "Мастерская Liv — в северном конце пристани Кабестана; сундук Marvon стоит внутри.",
	["Liv Rizzlefix"] = "Liv Rizzlefix",
	["Cleansed Water goes to the Emerald Sanctuary in Felwood: keep it for later."] = "«Очищенная вода» сдаётся в Изумрудном святилище в Оскверненном лесу: сохраните на потом.",
	["Islen camps on the shore just north of Ratchet."] = "Islen стоит лагерем на берегу сразу к северу от Кабестана.",
	["In the Valley of Spirits. Have the Wool, Silk and Mageweave in your bags."] = "В Аллее Духов. Держите в сумках шерсть, шёлк и магическую ткань.",
	["Both Runecloth donations are handed in later in the route: start saving Runecloth."] = "Оба пожертвования рунической ткани сдаются позже по маршруту: начинайте копить руническую ткань.",
	["Fly to Valormok"] = "Летите в Валормок",
	["Ride east to the ruins on the coast. Fill Cuely's four vials at the tide pools along the shore; Spitelash naga patrol between them."] = "Езжайте на восток к руинам на побережье. Наполните четыре склянки Cuely у приливных луж вдоль берега; между ними патрулируют наги Spitelash.",
	["The blood elves camp on the cliffs in the north-east, by the Bay of Storms."] = "Эльфы крови стоят лагерем на утёсах на северо-востоке, у Залива Бурь.",
	["Rimtori's camp is at the east end of the base camp. Read the Kaldorei Tome of Summoning there, then kill the Magus."] = "Лагерь Rimtori — в восточном конце базы. Прочитайте там Kaldorei Tome of Summoning, затем убейте мага.",
	["Magus Rimtori's camp"] = "Лагерь Magus Rimtori",
	["Ride back west to Valormok."] = "Езжайте обратно на запад в Валормок.",
	["Ag'tor Bloodfist"] = "Ag'tor Bloodfist",
	["Fly to Orgrimmar; Belgrom is in the Valley of Honor."] = "Летите в Оргриммар; Belgrom — в Аллее Чести.",
	["Belgrom Rockmaul"] = "Belgrom Rockmaul",
	["The zeppelin tower stands just north-east of Orgrimmar's main gate; take the Undercity zeppelin."] = "Башня дирижаблей стоит сразу к северо-востоку от главных ворот Оргриммара; садитесь на дирижабль в Подгород.",
	["The Apothecarium"] = "Аптекарий",
	["Good Luck Charm goes back to Janice Felstone in the Western Plaguelands: keep it."] = "«Талисман удачи» возвращается к Janice Felstone в Западных Чумных землях: сохраните.",
	["Royal Quarter"] = "Королевский квартал",
	["Owen Thadd"] = "Owen Thadd",
	["Prompt Potion Runner"] = "Prompt Potion Runner",
	["Eastern Plaguelands, Winterspring & Tanaris"] = "Восточные Чумные земли, Зимние Ключи и Танарис",
	["Fly to Light's Hope Chapel"] = "Летите в Часовню Последней Надежды",
	["The Undercity's flight master is in the Trade Quarter's west tower, outside the walls."] = "Распорядитель полётов Подгорода — в западной башне Торгового квартала, за стенами.",
	["Heroes of Darrowshire's items lie in the later Plaguelands zones: keep it."] = "Предметы для «Героев Дарроушира» лежат в следующих Чумных землях: сохраните задание.",
	["Plaguehounds and their runts roam the shores of the lake south-west of the chapel."] = "Чумные гончие и их щенки бродят по берегам озера к юго-западу от часовни.",
	["Lake Mereldar"] = "Озеро Мерелдар",
	["The shattered sword lies on the ground north-west of the lake."] = "Сломанный меч лежит на земле к северо-западу от озера.",
	["Sword of Marduk"] = "Меч Мардука",
	["The skull sits in the Pestilent Scar, among Blighted Horrors and Plague Monstrosities."] = "Череп лежит в Чумном Шраме, среди поражённых ужасов и чумных чудищ.",
	["The Pestilent Scar"] = "Чумной Шрам",
	["A torn scroll lies at the entrance of the Undercroft, the crypt south of the Marris Stead."] = "Порванный свиток лежит у входа в Подземелье — склеп к югу от поместья Маррисов.",
	["Hameya's scroll"] = "Свиток Hameya",
	["The Banshee Queen's champion holds the Marris Stead farmhouse."] = "Защитник Королевы Банши удерживает дом на поместье Маррисов.",
	["Nathanos Blightcaller"] = "Nathanos Blightcaller",
	["Plaguehound Runts and Plaguebats roam the hills north of the Marris Stead, Carrion Grubs crawl among them; work north toward Terrordale."] = "Щенки чумных гончих и чумные нетопыри бродят по холмам к северу от поместья Маррисов, среди них ползают падальные личинки; продвигайтесь на север к Долине Ужаса.",
	["The western hills"] = "Западные холмы",
	["Egan the ghost stands by a hut in Terrordale, in the north-west corner."] = "Призрак Egan стоит у хижины в Долине Ужаса, в северо-западном углу.",
	["Egan"] = "Egan",
	["The high elf Rangers, Pathstriders and Woodsmen guard the lodge by Northpass Tower; the Registry lies inside. Rangers reach 60: pull one at a time. Noxious Plaguebats fly over the fields on the way."] = "Высшие эльфы — следопыты, проводники и лесничие — охраняют сторожку у Башни Северного Перевала; реестр внутри. Следопыты до 60 уровня: тяните по одному. По пути над полями летают ядовитые чумные нетопыри.",
	["Quel'Lithien Lodge"] = "Сторожка Кель'Литиен",
	["Hameya hides among the Mossflayer trolls of Zul'Mashar, in the north-east corner."] = "Hameya прячется среди троллей Мшистой Шкуры в Зул'Машаре, в северо-восточном углу.",
	["Infiltrator Hameya"] = "Лазутчик Hameya",
	["Frenzied Plaguehounds and Monstrous Plaguebats share the fields around Northdale and Eastwall Tower, south of Zul'Mashar."] = "Бешеные чумные гончие и чудовищные чумные нетопыри делят поля вокруг Северной Долины и Восточной башни, к югу от Зул'Машара.",
	["Northdale"] = "Северная Долина",
	["Living Rot spoils within ten minutes: kill the town's Scourge quickly and grind the seven pieces with the Mortar and Pestle at once."] = "Живая гниль портится за десять минут: быстро перебейте Плеть в городе и сразу перетрите семь кусков пестиком и ступкой.",
	["Corin's Crossing"] = "Перекрёсток Корина",
	["Ride west to the Marris Stead."] = "Езжайте на запад к поместью Маррисов.",
	["The Mound of Dirt is just behind the Undercroft."] = "Земляной холмик — сразу за Подземельем.",
	["Hameya's mound"] = "Холмик Hameya",
	["Carlin Redpath"] = "Carlin Redpath",
	["Fly to the Undercity, take the zeppelin to Orgrimmar and fly on to Thunder Bluff."] = "Летите в Подгород, садитесь на дирижабль в Оргриммар и летите дальше в Громовой Утес.",
	["On Hunter Rise. Have the Wool, Silk and Mageweave in your bags."] = "На Вершине Охотников. Держите в сумках шерсть, шёлк и магическую ткань.",
	["Fly to Bloodvenom Post"] = "Летите на Заставу Кровавой Топи",
	["Trull Failbane"] = "Trull Failbane",
	["Only if you found a Winterfall Firewater flask in Winterspring: ride north up the road. The cauldron stands in Felpaw Village, just south-west of Timbermaw Hold; the Deadwood furbolgs there are hostile."] = "Только если вы нашли в Зимних Ключах флягу огненной воды Зимней Спячки: езжайте на север по дороге. Котёл стоит в Деревне Felpaw, сразу к юго-западу от Крепости Древобрюхов; фурболги Мертвого Леса там враждебны.",
	["Deadwood Cauldron"] = "Котёл Мертвого Леса",
	["Only if a Winterfall Ritual Totem dropped for you: Kernda waits at the Felwood entrance of Timbermaw Hold, and speaks to you only at Neutral with the Timbermaw."] = "Только если вам выпал Winterfall Ritual Totem: Kernda ждёт у входа в Крепость Древобрюхов со стороны Оскверненного леса и заговорит с вами, только если у вас нейтральная репутация с Древобрюхими.",
	["Kernda"] = "Kernda",
	["Both quests lead to Silithus: keep them."] = "Оба задания ведут в Силитус: сохраните их.",
	["Go through Timbermaw Hold and take the Moonglade branch of the tunnel. Rabine is in Nighthaven."] = "Пройдите через Крепость Древобрюхов и сверните в ответвление туннеля к Лунной поляне. Rabine — в Ночной Гавани.",
	["Rabine Saturna"] = "Rabine Saturna",
	["Toxic Horrors are in Felwood, on a later trip: keep it if you have it."] = "Токсичные ужасы — в Оскверненном лесу, в следующий раз: сохраните задание, если оно есть.",
	["Back through the tunnel and take the Winterspring exit, then ride south to Frostfire Hot Springs."] = "Обратно через туннель и через выход в Зимние Ключи, затем на юг к горячим источникам Морозного Огня.",
	["Ride east to Everlook and north out of it; the Moontouched Owlbeasts roam the hills of Frostsaber Rock's southern slopes. Pull them one at a time."] = "Езжайте на восток в Круговзор и на север из него; совухи, озарённые луной, бродят по холмам на южных склонах Скалы Ледопарда. Тяните по одной.",
	["Moontouched Owlbeasts"] = "Совухи, озарённые луной",
	["Hearth to Thunder Bluff"] = "Камень возвращения — в Громовой Утес",
	["Back to Thunder Bluff"] = "Обратно в Громовой Утес",
	["Use Umi's Mechanical Yeti on Sprinkle, the goblin girl in Gadgetzan. Quixxil and Legacki are scared later in the route."] = "Используйте Umi's Mechanical Yeti на Sprinkle — гоблинше в Прибамбасске. Quixxil и Legacki напугаете позже по маршруту.",
	["Sprinkle"] = "Sprinkle",
	["Linken's Sword goes back to Linken in Un'Goro: keep it."] = "Меч Linken возвращается к Linken в Ун'Горо: сохраните задание.",
	["Gaeriyan is a ghost at the graveyard just north of Gadgetzan; the Conspicuous Gravestone is south of it, outside the town wall."] = "Gaeriyan — призрак на кладбище сразу к северу от Прибамбасска; приметное надгробие — южнее, за городской стеной.",
	["Gaeriyan"] = "Gaeriyan",
	["Marvon camps by the Lost Rigger Cove road, south of Gadgetzan."] = "Marvon стоит лагерем у дороги к Бухте Пропавшего Такелажника, к югу от Прибамбасска.",
	["Fly to Camp Mojache. The hippogryph nests are in the south of Feralas; each holds an egg for the Egg-O-Matic."] = "Летите в Лагерь Мохаче. Гнёзда гиппогрифов — на юге Фераласа; в каждом есть яйцо для Egg-O-Matic.",
	["Hippogryph eggs"] = "Яйца гиппогрифов",
	["Fly to Marshal's Refuge"] = "Летите в Убежище Маршалла",
	["Fly to Marshal's Refuge, then ride south-west through Un'Goro to the pass into Silithus. The next guide opens at Valor's Rest, where the pass comes out."] = "Летите в Убежище Маршалла, затем езжайте на юго-запад через Ун'Горо к перевалу в Силитус. Следующий гид начинается в Приюте Доблести, где выходит перевал.",
	["On to Silithus"] = "Дальше в Силитус",
	["Silithus, Western Plaguelands & Eastern Plaguelands"] = "Силитус, Западные и Восточные Чумные земли",
	["The pass from Un'Goro comes out at Valor's Rest, the graveyard in north-east Silithus. Layo stands among the graves."] = "Перевал из Ун'Горо выходит к Приюту Доблести — кладбищу на северо-востоке Силитуса. Layo стоит среди могил.",
	["Layo Starstrike"] = "Layo Starstrike",
	["Ride south-west to the ruins of Southwind Village. The Dusty Reliquary for Rabine Saturna sits inside one of the ruined houses."] = "Езжайте на юго-запад к руинам деревни Южного Ветра. Пыльный реликварий для Rabine Saturna стоит в одном из разрушенных домов.",
	["The Spirits of Southwind"] = "Духи Южного Ветра",
	["Back to Southwind and climb the tower. Stirring the hive at the top brings out Hive'Ashi Ambushers; one carries the Encrusted Silithid Object."] = "Обратно к деревне Южного Ветра и поднимитесь на башню. Если потревожить улей наверху, выйдут засадники Улья Аши; у одного из них — Encrusted Silithid Object.",
	["Hive in the Tower"] = "Улей в башне",
	["Ride west to the walled hold in the middle of the desert."] = "Езжайте на запад к крепости за стенами посреди пустыни.",
	["Cenarion Hold"] = "Крепость Кенария",
	["Dredge Strikers, Stonelash Scorpids and Sand Skitterers share the sands just north of the hold."] = "Землеройки, каменохвостые скорпиды и песчаные бегуны делят пески сразу к северу от крепости.",
	["Dredge and scorpids"] = "Землеройки и скорпиды",
	["The glowing tablet fragments lie around the Twilight camp in the far north-west; the Dust Stormers and Desert Rumblers there drop them too."] = "Светящиеся фрагменты скрижалей лежат вокруг лагеря Сумеречного Молота на дальнем северо-западе; их же роняют пыльные бури и пустынные громовики там.",
	["Twilight Base Camp"] = "Лагерь Сумеречного Молота",
	["Ride south-east to Ortell's Hideout under the Un'Goro cliffs."] = "Езжайте на юго-восток к укрытию Ortell под утёсами Ун'Горо.",
	["Hermit Ortell"] = "Hermit Ortell",
	["Ride west to the Horde camp north of Hive'Regal."] = "Езжайте на запад к лагерю Орды к северу от Улья Регал.",
	["General Kirika"] = "General Kirika",
	["Silithyst geysers erupt across the southern desert. Walk into the Silithyst one leaves behind and carry it to the Horde's Silithyst Extractor at Kirika's camp; fighting or mounting drops it."] = "Гейзеры силитиста извергаются по всей южной пустыне. Войдите в оставшийся силитист и отнесите его к экстрактору силитиста Орды в лагере Kirika; бой или посадка на маунта его роняют.",
	["Scouring the Desert"] = "Прочёсывая пустыню",
	["Stonelash Flayers and Rock Stalkers roam the dunes south-west of Kirika's camp."] = "Каменохвостые живодёры и скальные ловчие бродят по дюнам к юго-западу от лагеря Kirika.",
	["Flayers and Rock Stalkers"] = "Живодёры и скальные ловчие",
	["Twilight Keeper Exeter walks the Vanguard camp in the far south-west. Every cultist here drops Encrypted Twilight Texts, quest or not: collect twenty, ten for Bor Wildmane and ten for Ortell."] = "Сумеречный хранитель Exeter ходит по лагерю авангарда на дальнем юго-западе. С каждого культиста здесь выпадают Encrypted Twilight Texts, есть задание или нет: соберите двадцать — десять для Bor Wildmane и десять для Ortell.",
	["Twilight Vanguard"] = "Сумеречный авангард",
	["Head north along the western dunes; Dredge Crushers and Stonelash Pincers range from here back toward the hold."] = "Идите на север по западным дюнам; дробители-землеройки и каменохвостые клешни бродят отсюда до самой крепости.",
	["Dredge Crushers and Pincers"] = "Дробители и клешни",
	["Twilight Keeper Mayna holds the camp in the west."] = "Сумеречная хранительница Mayna держит лагерь на западе.",
	["Twilight Post"] = "Сумеречный пост",
	["Twilight Keeper Havunth stands in the outpost west of Cenarion Hold. Top your Encrypted Twilight Texts up to twenty on the cultists here."] = "Сумеречный хранитель Havunth стоит на заставе к западу от Крепости Кенария. Доберите здесь на культистах Encrypted Twilight Texts до двадцати.",
	["Twilight Outpost"] = "Сумеречная застава",
	["The satchel lies in the mountains of the far south, past Bronzebeard's Encampment. Deathclasp, an elite scorpid, patrols near it: grab it while he is away."] = "Сумка лежит в горах на дальнем юге, за лагерем Бронзоборода. Рядом патрулирует Deathclasp, элитный скорпид: хватайте, пока его нет.",
	["Noggle's Lost Satchel"] = "Потерянная сумка Noggle",
	["Ride north-east to Ortell's Hideout."] = "Езжайте на северо-восток к укрытию Ortell.",
	["Hearth to Cenarion Hold"] = "Камень возвращения — в Крепость Кенария",
	["Mar'alith's Dearest Natalia needs level 58 and leads into Hive'Regal among elites. Skip it."] = "«Дорогая Наталия» от Mar'alith требует 58 уровня и ведёт в Улей Регал к элитным. Пропустите.",
	["Back to Cenarion Hold"] = "Обратно в Крепость Кенария",
	["Ride north-east to Valor's Rest; you leave Silithus through the pass beside it."] = "Езжайте на северо-восток к Приюту Доблести; вы покидаете Силитус через перевал рядом.",
	["Keep Linken's Memory: Eridan Bluewind is at the Emerald Sanctuary, on the next guide's way through Felwood."] = "Сохраните «Память Linken»: Eridan Bluewind — в Изумрудном святилище, по пути следующего гида через Оскверненный лес.",
	["Through the pass and east along the northern cliffs to Marshal's Refuge. Linken stands by the cave; J.D. Collie is inside it."] = "Через перевал и на восток вдоль северных утёсов к Убежищу Маршалла. Linken стоит у пещеры; J.D. Collie — внутри.",
	["Fly to Gadgetzan. The Egg-O-Matic stands in the middle of town."] = "Летите в Прибамбасск. Egg-O-Matic стоит в центре города.",
	["Fly to Orgrimmar and train."] = "Летите в Оргриммар и потренируйтесь.",
	["Take the zeppelin from the tower outside Orgrimmar to Tirisfal Glades and ride into the Undercity. Lady Sylvanas holds the Royal Quarter."] = "Садитесь на дирижабль с башни у Оргриммара до Тирисфальских лесов и езжайте в Подгород. Леди Сильвана — в Королевском квартале.",
	["The Undercity"] = "Подгород",
	["Ride east along the road to the Bulwark on the border."] = "Езжайте на восток по дороге к Бастиону на границе.",
	["Janice Felstone's farm is the first one east of the Bulwark. Jabbering Ghouls on the farm carry the other half of her charm; Cauldron Lord Bilemaw guards the cauldron in the field."] = "Ферма Janice Felstone — первая к востоку от Бастиона. У болтливых упырей на ферме вторая половинка её талисмана; Cauldron Lord Bilemaw охраняет котёл в поле.",
	["Felstone Field"] = "Поле Камня Скверны",
	["Ride south into Andorhal. Chromie waits in the ruined inn on the west side of town. Stand in the doorway of each of the four towers with the Beacon Torch to mark it; keep to the edges of town. Use the Temporal Displacer by the silos in the middle of town to bring out Temporal Parasites."] = "Езжайте на юг в Андорал. Chromie ждёт в разрушенной таверне на западной стороне города. Встаньте в дверях каждой из четырёх башен с Beacon Torch, чтобы отметить её; держитесь окраин города. Используйте Temporal Displacer у силосных башен в центре города, чтобы выманить временных паразитов.",
	["Andorhal watchtowers and silos"] = "Сторожевые башни и силосы Андорала",
	["Dithers offers Skeletal Fragments (Scholomance). Skip it."] = "Dithers предлагает «Фрагменты скелетов» (Некроситет). Пропустите.",
	["East along the road, Cauldron Lord Malvinious guards the cauldron at Dalson's Tears."] = "На восток по дороге: Cauldron Lord Malvinious охраняет котёл у Слез Далсона.",
	["Dalson's Tears"] = "Слезы Далсона",
	["North to the lumber camp; set the termite barrel down in the middle of the mill."] = "На север к лесопилке; поставьте бочку с термитами посреди лесопилки.",
	["The libram lies further north, on the way to Hearthglen."] = "Либрам лежит севернее, по пути к Дольному Очагу.",
	["Davil's Libram"] = "Либрам Davil",
	["Ride east to Tirion's hut by the Thondroril River and hear him out."] = "Езжайте на восток к хижине Tirion у реки Тондрорил и выслушайте его.",
	["The shield lies at Gahrron's Withering, south of Tirion's hut."] = "Щит лежит в Увядании Гаррона, к югу от хижины Tirion.",
	["Redpath's Shield"] = "Щит Redpath",
	["Ride east across the plaguelands to the chapel."] = "Езжайте на восток через Чумные земли к часовне.",
	["Scourge Champions roam the Noxious Glade, north of the chapel. Pass Carlin's Mystic Crystal over each one you kill: the skulls that resonate are the ones he wants."] = "Поборники Плети бродят по Ядовитой поляне к северу от часовни. Проводите Mystic Crystal Carlin над каждым убитым: нужны те черепа, что откликаются.",
	["Scourge Champions"] = "Поборники Плети",
	["Pamela's own errand is not on this route. Skip it."] = "Собственного поручения Pamela нет в этом маршруте. Пропустите.",
	["Ride to Darrowshire in the south-west; Pamela plays among the houses. Mercutio Filthgorger lurks in the Undercroft, the crypt just west of the town."] = "Езжайте в Дарроушир на юго-западе; Pamela играет среди домов. Mercutio Filthgorger прячется в Подземелье — склепе сразу к западу от города.",
	["Pamela and the Undercroft"] = "Pamela и Подземелье",
	["Nathanos' errands are not on this route. Skip them."] = "Поручений Nathanos нет в этом маршруте. Пропустите.",
	["The Banshee Queen's champion holds the Marris Stead farmhouse, north of the Undercroft."] = "Защитник Королевы Банши удерживает дом на поместье Маррисов, к северу от Подземелья.",
	["Tirion's next task, Of Lost Honor, is not on this route. Skip it."] = "Следующего задания Tirion «Об утраченной чести» нет в этом маршруте. Пропустите.",
	["Ride north-west to Tirion's hut."] = "Езжайте на северо-запад к хижине Tirion.",
	["Chromie's Battle of Darrowshire ends against elites. Skip it."] = "«Битва за Дарроушир» от Chromie заканчивается боем с элитными. Пропустите.",
	["Ride south-west to Chromie in Andorhal."] = "Езжайте на юго-запад к Chromie в Андорал.",
	["West to the Bulwark. The next guide starts in the Undercity, a short ride west."] = "На запад к Бастиону. Следующий гид начинается в Подгороде, чуть западнее.",
	["Get the flight path at Cenarion Hold"] = "Возьмите точку полёта в Крепости Кенария",
	["Felwood, Moonglade & Winterspring"] = "Оскверненный лес, Лунная поляна и Зимние Ключи",
	["From the Undercity, take the zeppelin from the tower outside the city to Orgrimmar."] = "Из Подгорода садитесь на дирижабль с башни у города до Оргриммара.",
	["Eridan's Silver Heart needs an Irontree Heart from northern Felwood and a ride back here. Skip it."] = "«Серебряное сердце» Eridan требует сердце Железнолесья из северного Оскверненного леса и возвращения сюда. Пропустите.",
	["Fly to Splintertree Post and ride north-west along the road out of Ashenvale into Felwood. The Emerald Sanctuary is the druids' camp just past the border."] = "Летите на Заставу Расщепленного Дерева и езжайте на северо-запад по дороге из Ясеневого леса в Оскверненный лес. Изумрудное святилище — лагерь друидов сразу за границей.",
	["The Emerald Sanctuary"] = "Изумрудное святилище",
	["Ride north-west to Jaedenar. The four braziers stand among the Shadow Council's buildings; use the Cleansed Water on each one."] = "Езжайте на северо-запад к Джеденару. Четыре жаровни стоят среди построек Совета Теней; используйте очищенную воду на каждой.",
	["Dousing the Flames of Protection"] = "Гашение пламени защиты",
	["Back south to the Sanctuary, a short ride."] = "Обратно на юг к святилищу, недалеко.",
	["Greta Mosshoof"] = "Greta Mosshoof",
	["Moora, Salia and Shadow Lord Fel'dan wait at the back of Shadow Hold, the cave in Jaedenar's north. Clear the tunnel as you go."] = "Moora, Salia и Shadow Lord Fel'dan ждут в глубине Темной Твердыни — пещеры на севере Джеденара. Расчищайте туннель по пути.",
	["A Final Blow"] = "Последний удар",
	["South to the Sanctuary once more."] = "Ещё раз на юг к святилищу.",
	["Trull's next Wild Guardians would bring you back here from Winterspring. Skip it."] = "Следующее задание Trull «Дикие стражи» вернуло бы вас сюда из Зимних Ключей. Пропустите.",
	["Ride north along the road, past Jaedenar, to Bloodvenom Post."] = "Езжайте на север по дороге мимо Джеденара к Заставе Кровавой Топи.",
	["Only if Donova gave you Toxic Horrors: ride north up the Felwood road to Irontree Woods; the Toxic Horrors ooze between the trees."] = "Только если Donova дала вам «Токсичные ужасы»: езжайте на север по дороге Оскверненного леса к Железнолесью; токсичные ужасы ползают между деревьями.",
	["Toxic Horrors"] = "Токсичные ужасы",
	["Only with 30 Runecloth, and only at Neutral with the Timbermaw: follow the road north to Timbermaw Hold; Meilosh trades just inside the entrance."] = "Только если есть 30 рунической ткани и нейтральная репутация с Древобрюхими: идите по дороге на север к Крепости Древобрюхов; Meilosh торгует сразу у входа.",
	["Meilosh"] = "Meilosh",
	["Through the Timbermaw tunnel to Moonglade. Umber reads in a house in Nighthaven."] = "Через туннель Древобрюхов на Лунную поляну. Umber читает в доме в Ночной Гавани.",
	["Umber"] = "Umber",
	["Rabine's Shards of the Felvine needs Dire Maul. Skip it."] = "«Осколки Скверноплода» от Rabine требуют Забытый Город. Пропустите.",
	["Back into the Timbermaw tunnel and take the Winterspring exit; Donova camps by the hot springs just outside."] = "Обратно в туннель Древобрюхов и через выход в Зимние Ключи; Donova стоит лагерем у горячих источников сразу снаружи.",
	["Donova next sends you after High Chief Winterfall, an elite in his cave. Skip it."] = "Дальше Donova отправит вас за High Chief Winterfall — элитным в его пещере. Пропустите.",
	["Only if you carry Winterfall Runners: the runners walk the road from Timbermaw Hold toward Winterfall Village in small groups; wait by the road near Donova and kill them as they pass. Each one carries a crate."] = "Только если у вас задание на гонцов Зимней Спячки: гонцы ходят небольшими группами по дороге от Крепости Древобрюхов к Деревне Зимней Спячки; ждите у дороги рядом с Donova и убивайте их, когда проходят. У каждого есть ящик.",
	["Winterfall Runners"] = "Гонцы Зимней Спячки",
	["Ride east along the road to Everlook."] = "Езжайте на восток по дороге в Круговзор.",
	["Optional: with a group, a 55-60 dungeon replaces the grind below."] = "Необязательно: с группой подземелье 55-60 заменит прокачку ниже.",
	["Optional. Running Stratholme, Scholomance, Lower Blackrock Spire or Blackrock Depths with a group instead of grinding gets you there faster."] = "Необязательно. Стратхольм, Некроситет, Нижний ярус Черной горы или Глубины Черной горы с группой вместо прокачки на мобах — быстрее.",
	["Dungeon instead of grinding"] = "Подземелье вместо прокачки",
	["The quests run out here. Rabid Shardtooths prowl Frostwhisper Gorge in southern Winterspring, south of the road from Everlook."] = "Задания здесь заканчиваются. Бешеные осколкозубы рыщут по Ущелью Ледяного Шёпота на юге Зимних Ключей, к югу от дороги из Круговзора.",
	["Grind to 60"] = "Докачайтесь до 60",
	["Frostwhisper Gorge"] = "Ущелье Ледяного Шёпота",
}

ns.AddLocale("ruRU", R)
